function week(number, title, pages, overview, references) {
  const w = { schemaVersion: 1, id: `w${String(number).padStart(2, '0')}`, number, exam: 'final', title, overview,
    source: { filename: `[교안]인터넷보안_${String(number).padStart(2, '0')}.pdf`, pages }, objectives: [], questions: [], coverage: [], corrections: [], references };
  weeks.push(w); return w;
}
function objective(w, slug, title, pages, why, explanation, takeaway, comparison, situation, steps, answer, mistake, prompt, checkAnswer, correctionIds = [], prerequisites = []) {
  const id = `${w.id}-${slug}`;
  w.objectives.push({ id, title, pages, why, explanation, keyTakeaway: takeaway,
    comparison: comparison.map(([term, meaning, example]) => ({ term, meaning, example })),
    workedExample: { situation, steps, answer }, commonMistakes: [mistake], check: { prompt, answer: checkAnswer }, prerequisites, correctionIds: correctionIds.map(s => `${w.id}-${s}`) });
  return id;
}
function q(w, oid, family, kind, pages, prompt, correct, options, explanation, context = '', difficulty = 2) {
  const id = `${w.id}-q${String(w.questions.length + 1).padStart(3, '0')}`;
  w.questions.push({ id, objectiveId: oid, family: `${w.id}-${family}`, kind, difficulty, prompt, ...(context ? { context } : {}),
    options: options.map(([text, explanation], i) => ({ id: 'abcd'[i], text, explanation })), answerId: 'abcd'[correct], explanation, sourcePages: pages });
}
function correction(w, slug, pages, issue, corrected, examGuidance, status, references) {
  w.corrections.push({ id: `${w.id}-${slug}`, pages, issue, corrected, examGuidance, status, references });
}
function coverage(w, pages, topic, objectiveIds, status = 'covered', note = '') {
  w.coverage.push({ pages, topic, objectiveIds, status, note });
}

