coverage(w9,[24], '해시 보호·도구 명칭의 역사·트로이 목마·백도어', [passwords,persistence], 'historical', '자격증명 덤프와 크래킹 절차는 가상 위험 해석으로 대체.');
coverage(w9,[25,26], '프로세스 영역·버퍼 경계·반환 정보 그림의 한계', [buffer]);
coverage(w9,[27], '포맷 지시·데이터 분리·오류 위험', [format]);
coverage(w9,[28], '학습정리 및 추가 학습요소 안내', [sniff,spoof,dos,os], 'covered', '스니핑/스푸핑의 부정확한 요약은 정정 링크로 대체. 추가 학습요소 표지는 행정 요소.');

const w10 = week(10,'무선 인터넷: 전파 노출과 인증·암호화',28,
  '무선 신호의 수신 범위와 네트워크 가입·암호 해독은 서로 다르다. 탐색 프레임과 주소 필터의 한계를 이해하고 WEP의 역사적 결함을 현대 WPA 구성과 구분한다. 모든 사례·기록은 가상이며 무선 수집·방해·키 추측 활동은 수행하지 않는다.',
  [R.wlan,R.wep,R.withdrawn,R.wpa3,R.retail,R.latte,R.auth]);
const topology = objective(w10,'topology','무선 접속 구조와 인터넷 연결의 차이',[1,2,3,28],
  'Wi-Fi 신호가 잡힌다고 인터넷에 연결되거나 신뢰할 수 있는 내부망에 들어간 것은 아니다.',
  ['무선 인터넷은 케이블 대신 무선 구간을 포함해 인터넷을 이용하는 넓은 표현이다. Wi-Fi는 IEEE 802.11 계열의 무선 LAN 맥락이며 블루투스와 이동통신은 같은 기술명이 아니다. 교안의 Ad-Hoc 그림은 단말끼리 직접 통신하는 구조, Infrastructure 그림은 AP를 중심으로 단말이 통신하는 구조를 보여 준다.',
   'AP는 무선 단말을 분배 시스템에 연결하는 역할을 하며, 인터넷 경로와 방화벽·라우팅·상위 연결은 별도 구성이다. 핫스팟은 보통 접속을 제공하는 장소·서비스를 말하므로 AP 장치와 정확히 같은 말로만 쓰지는 않는다. 교안의 과거 장소별 이용 통계는 당시 배경이며 현재 이용 순위로 일반화하지 않는다. 구조를 구분하면 장애가 무선 연결인지 상위 인터넷 경로인지 나누어 볼 수 있다.'],
  '무선 연결, AP 가입, 인터넷 도달, 서비스 인증은 각각 확인한다.',
  [['Ad-Hoc','단말 간 직접 통신하는 구성','가상 단말끼리 로컬 자료 교환'],['Infrastructure','AP를 중심으로 구성','단말들이 사무실 AP에 연결']],
  '가상 태블릿은 AP에 연결됐지만 상위 인터넷 회선이 끊겼다.',
  ['AP와 태블릿 사이 무선 연결 성공을 인터넷 전체 성공과 분리한다.','상위 라우팅·회선·이름 해석 등 다음 구간을 확인한다.'],
  'Wi-Fi 연결 표시만으로 인터넷 도달성을 확정하지 않는다.',
  'AP가 없으면 어떤 무선 통신도 불가능하다는 생각은 단말 간 구성과 다른 무선 기술을 놓친다.',
  'AP 연결 성공 후에도 웹 서비스 로그인이 따로 필요한 이유는?', '무선 구간 가입과 응용 서비스의 사용자 인증은 다른 경계이기 때문이다.', ['wireless-terms']);
q(w10,topology,'adhoc-vs-infrastructure','contrast',[2,3],'가상 단말들이 AP 없이 서로 직접 자료를 교환한다. 교안의 구성 분류는?',1,[["Infrastructure","AP를 중심으로 접속하는 구성과 구분한다."],["Ad-Hoc","교안에서는 AP 없이 단말이 직접 교환하는 구성을 Ad-Hoc으로 분류한다."],["인프라 AP의 유선 백홀","상위망 연결 방식이며 AP 없는 단말 직접 교환의 분류가 아니다."],["인터넷 핫스팟 접속","인터넷 접속 제공 서비스라는 조건은 제시되지 않았다."]],'AP의 존재와 역할을 기준으로 두 기본 구성을 구별한다.');
q(w10,topology,'association-not-internet','application',[1,3],'AP 연결은 정상이나 상위 인터넷 회선이 끊겼다. 타당한 결론은?',0,[["무선 LAN 연결은 있어도 인터넷은 안 될 수 있다","단말과 AP의 무선 연결과 상위 인터넷 회선은 서로 다른 구간이다."],["상위 회선이 끊기면 AP와의 무선 연결도 반드시 끊긴다","상위망 장애가 곧 무선 링크 단절인 것은 아니다."],["AP 신호가 정상이면 외부 인터넷 도달성도 보장된다","신호 수신만으로 상위 경로의 정상 여부를 보증할 수 없다."],["인터넷 장애는 무선 비밀번호가 틀렸다는 뜻이다","상위 회선 장애와 가입 인증 실패는 다른 원인이다."]],'연결 상태를 구간별로 구분하면 장애 원인을 좁힐 수 있다.');
q(w10,topology,'wifi-vs-bluetooth','concept',[1,2],'Wi-Fi와 블루투스를 설명하는 정확한 문장은?',3,[["블루투스 장치는 Wi-Fi AP에 별도 지원 없이 항상 가입한다","서로 다른 규격의 지원과 접속 조건이 필요하다."],["두 기술은 이름만 다르고 프레임 형식과 인증 절차가 같다","무선이라는 이유로 프로토콜이 동일해지지 않는다."],["두 기술은 주파수 대역이 겹치면 상호 가입 인증도 호환된다","사용 주파수의 중첩은 프레임·가입 절차의 호환성을 보증하지 않는다."],["모두 무선 이용 맥락에 등장하지만 동일 규격은 아니다","무선을 쓴다는 공통점만으로 동일한 규격이나 연결 방식을 뜻하지 않는다."]],'무선 인터넷이라는 넓은 표현을 특정 규격 이름과 같은 뜻으로 쓰지 않는다.');
q(w10,topology,'ap-hotspot','concept',[3],'AP와 핫스팟 용어를 다룰 때 적절한 구분은?',2,[["AP는 인터넷 회선 자체이고 핫스팟은 무선 암호 방식이다","회선·접속 장치·암호 방식을 혼동했다."],["핫스팟이라고 부르면 가입 인증과 암호화가 자동 보장된다","서비스 이름은 실제 보안 설정을 보증하지 않는다."],["AP는 접속 장치 역할, 핫스팟은 보통 접속 제공 장소·서비스 맥락이다","역할과 접속 제공 맥락을 나누되 용어 사용에 따른 겹침은 있을 수 있다."],["AP가 있는 장소는 상위 회선 상태와 관계없이 인터넷을 제공한다","인터넷 제공에는 상위 연결의 정상 동작도 필요하다."]],'일상적 혼용은 가능하지만 구성 문제를 설명할 때 장치와 서비스를 구별하면 명확하다.');
q(w10,topology,'historical-usage-chart','evidence',[3],'오래된 장소별 Wi-Fi 이용 그래프를 보고 현재 카페 이용 비중을 확정하려 한다. 적절한 평가는?',1,[["그래프의 장소 분류가 같으면 과거 비중을 현재에도 그대로 적용한다","분류가 같아도 이용 행태와 표본은 시간에 따라 달라질 수 있다."],["당시 배경 자료이며 현재 비중에는 새 자료가 필요하다","조사 시점과 모집단이 다른 수치를 현재 비중으로 확정할 수 없다."],["가장 큰 과거 항목은 현재에도 반드시 가장 크다","과거 순위가 현재 순위를 보증하지 않는다."],["출처가 있는 과거 수치는 현재 표본 조사보다 항상 우선한다","출처의 존재와 현재 상황에 대한 적합성은 별개다."]],'오래된 수치는 현재 사실로 채점하지 않고 당시 이용 배경으로만 다룬다.');

const risks = objective(w10,'threats','도청·방해·비인가 AP를 구별',[4,5,6,7,8,9],
  '같은 무선 장애라도 정보 노출, 접속 유도, 전파 방해는 원인과 대응이 다르다.',
  ['전파는 벽이나 건물 경계와 정확히 일치하지 않아 외부에서도 일부 신호를 수신할 수 있다. 수동 모니터링은 내용을 바꾸지 않아 탐지가 어려울 수 있지만 암호화된 내용까지 자동 해독한다는 뜻은 아니다. 대량 트래픽이나 방해 전파는 이용 가능성을 떨어뜨리는 위협이고, 끊김 자체가 반드시 공격 증거는 아니다.',
   'Rogue AP는 조직이 승인하지 않은 접속점으로 관리 경계를 우회하거나 사용자를 속이는 경로가 될 수 있다. 이름이 익숙하더라도 정당한 AP라는 증거는 아니다. 교안의 은행·백화점 사례는 역사적 동기를, 소매업체 사건은 약한 무선 구간 이후 내부망으로 피해가 이어질 수 있음을 보여 준다. 카페라떼는 WEP·저장된 접속 설정의 과거 위험으로 이해하며 장소·시간·모든 암호 방식에 보편 적용하지 않는다.'],
  '무선 신호를 받았다는 사실과 가입 허가·평문 해독·공격 확정을 분리한다.',
  [['도청','통신 관찰을 통한 정보 획득 시도','암호문과 전송 시점의 관찰'],['서비스 거부','정상 무선 이용을 방해','가상 채널 혼잡과 연결 실패'],['비인가 AP','승인되지 않은 접속점','관리 목록에 없는 같은 이름 AP']],
  '가상 회사에서 익숙한 SSID의 새 AP가 보이고 일부 단말만 접속 안내 화면을 받았다.',
  ['SSID만으로 승인된 장치라고 판단하지 않고 관리 자산·보안 구성과 비교한다.','자격증명 입력을 보류하고 연결 기록과 사용자 영향 범위를 조사한다.'],
  '친숙한 네트워크 이름은 신원 인증의 대체가 아니다.',
  '연결이 끊겼으니 반드시 방해 전파 공격이라는 생각은 혼잡·거리·설정 오류 같은 다른 원인을 배제하지 못한다.',
  '무선망 암호화가 있어도 AP 관리와 내부망 분리가 필요한 이유는?', '키 유출·오설정·비인가 장치 등 다른 경로가 남고 한 구간의 실패가 전체 내부 자원으로 확산되지 않게 해야 하기 때문이다.', ['incident-facts','latte-date','capture-visibility']);
q(w10,risks,'rogue-ssid','application',[9],'가상 회사 관리 목록에 없는 AP가 회사와 같은 SSID를 사용한다. 옳은 대응은?',2,[["회사와 SSID가 같으므로 승인된 장치로 등록한다","SSID 일치는 관리 주체의 동일성을 보증하지 않는다."],["목록에 없으므로 접속 주체와 변경 이력 확인 없이 악성으로 확정한다","누락된 승인 변경 등 대안도 조사해야 한다."],["승인 장치 목록·보안 설정·접속 기록과 대조한다","이름만으로 승인 여부나 장치 정체를 확정하지 않는다."],["신호가 가장 강하면 회사 장치라는 증거로 본다","수신 세기는 소유자나 승인 여부의 인증 수단이 아니다."]],'비인가 AP 판단은 이름보다 승인된 구성과 실제 장치 관계를 기준으로 한다.');
q(w10,risks,'disruption-not-attribution','evidence',[8],'가상 회의 중 무선 연결이 자주 끊긴다. 이 사실만으로 확정할 수 없는 것은?',0,[["의도적 전파 방해 공격이다","혼잡·간섭·장치 문제 등 대안을 배제하지 못했다."],["무선 연결의 가용성 문제가 관찰되었다","잦은 연결 단절이 직접 뒷받침하는 제한된 결론이다."],["채널 혼잡과 주변 간섭을 점검할 이유가 있다","가능한 원인을 구분하기 위한 적절한 후속 점검이다."],["단말과 AP의 상태·기록을 함께 확인해야 한다","공격으로 단정하기 전에 관련 구간을 대조해야 한다."]],'장애 관찰과 악의적 원인·행위자 특정은 별도 증거가 필요하다.');
q(w10,risks,'retail-segmentation','application',[4,5,6],'약한 무선 구간 하나가 내부 결제 자료까지 영향을 주지 않게 하는 추가 원칙은?',1,[["무선 비밀번호 하나를 모든 내부 서비스 인증에 재사용한다","하나의 비밀 유출이 여러 경계로 확대될 수 있다."],["무선 가입 통제와 내부 자원 분리·최소 권한을 결합한다","한 구간의 실패가 민감 자원 접근으로 곧바로 확대되지 않게 한다."],["SSID만 숨기고 내부 결제 자원은 모든 가입자에게 개방한다","이름 숨김은 내부 자원 인가를 대신하지 않는다."],["가입에 성공한 장치는 모든 내부 자원에 신뢰를 부여한다","네트워크 가입과 각 자원에 대한 권한은 구분해야 한다."]],'무선 보안과 내부 접근 제어는 함께 설계해야 한다.');
q(w10,risks,'latte-historical','concept',[7],'카페라떼 사례에서 배워야 할 핵심은?',3,[["AP가 현재 꺼져 있으면 단말의 저장된 무선 설정은 점검할 필요가 없다","단말의 접속 동작도 별도 검토 대상이다."],["WEP 비밀번호를 숨기면 IV 재사용 문제도 사라진다","비밀 값 비공개와 공개 IV·프로토콜 구성 약점은 별개다."],["이 사례는 현재의 모든 무선 보호 방식이 같은 조건으로 깨진다는 증거다","구형 방식의 사례를 다른 보호 구성 전체로 일반화할 수 없다."],["구형 WEP와 단말의 접속 동작에도 위험이 있어 설정을 관리해야 한다","역사 사례는 AP뿐 아니라 단말과 구형 보호 구성도 검토하게 한다."]],'교안의 고정 시간과 발표연도는 정정하며 공격 실행 절차를 학습 활동으로 만들지 않는다.');
q(w10,risks,'wireless-eavesdrop-encryption','contrast',[8,21],'적절히 보호된 무선·TLS 통신의 패킷을 수신했다. 곧바로 모든 사용자 평문을 알 수 있다는 주장은?',0,[["틀리다. 수신 범위와 암호 해독 조건을 별도로 보아야 한다","프레임 수신이 적절히 암호화된 내용의 평문 획득을 뜻하지 않는다."],["옳다. 무선 구간을 복호화하면 내부 TLS 보호도 자동으로 해제된다","무선 링크 보호와 응용 TLS 보호는 별개의 암호화 경계다."],["틀리다. 암호화가 있으면 통신의 존재나 크기도 전혀 관찰할 수 없다","내용 기밀성과 관찰 가능한 메타데이터를 구분해야 한다."],["옳다. 서버 인증서의 공개키만 있으면 관찰한 TLS의 본문을 모두 복호화한다","공개 인증 자료의 보유는 세션의 비밀 자료 획득과 다르다."]],'무선 매체의 노출은 암호화 필요성을 높이지만 암호문이 자동 평문이 되는 것은 아니다.');

const discovery = objective(w10,'discovery','탐색 프레임과 지도 기록의 의미',[10,11,12,13,15,16,17,18],
  '주변 AP가 표시되는 과정과 네트워크 사용 허가는 다르다. 탐색 결과를 자산 점검 자료로 올바르게 읽는다.',
  ['능동 탐색은 단말이 Probe Request를 보내고 AP의 Probe Response를 받는 흐름이며, 수동 탐색은 이미 전송되는 Beacon 등을 수신한다. Beacon은 존재·지원 능력·시간 관련 정보를 제공한다. 탐색이 성공해도 암호·인증·접근 정책을 충족한 가입이나 인터넷 이용이 보장되지는 않는다.',
   '교안의 WarWalking·WarDriving은 이동 방식에 따른 무선 환경 발견, WarChalking은 발견한 정보를 기호로 표시하는 역사적 이름이다. 사진과 지도는 발견 위치·장비 사용의 예이지 접속 허가나 해독 성공의 증거가 아니다. 신호가 보이는 위치는 전파 환경과 관찰 시점에 따라 달라진다. 숨긴 SSID도 무선 통신의 모든 식별 흔적을 없애는 암호화가 아니므로 숨김만으로 보안을 대신할 수 없다.'],
  '탐색 정보는 환경 발견의 단서이며 인증·인가·내용 해독의 증거와 다르다.',
  [['능동 탐색','탐색 요청을 보내 응답 관찰','가상 로그의 Probe Request/Response'],['수동 탐색','기존 공지 프레임을 수신','가상 로그의 주기적 Beacon']],
  '가상 로그에는 단말 송신 없이 Beacon 수신만 반복된다.',
  ['송신 요청이 없고 AP 공지를 받았다는 점에서 수동 탐색으로 분류한다.','기록에 가입 성공·인터넷 도달 증거가 없는 점을 분리해 적는다.'],
  '발견은 확인되지만 사용 허가까지 확인된 것은 아니다.',
  '무선 지도에 점이 찍혔으니 해당 망이 공개 사용 가능하다는 판단은 발견과 허가를 혼동한다.',
  '같은 지역을 재관찰했을 때 AP 목록이 달라질 수 있는 이유는?', '장치 동작·관찰 시간·채널·수신 위치와 신호 환경이 달라질 수 있어 목록은 조건에 묶인 관찰이기 때문이다.', ['beacon-scope']);
q(w10,discovery,'probe-vs-beacon','evidence',[11,12],'가상 로그: 단말 송신 Probe Request, AP 수신 응답 Probe Response. 해당 탐색은?',0,[["능동 탐색","단말이 Probe Request를 먼저 보내 응답을 얻는 흐름이다."],["수동 탐색","Beacon 등을 기다려 수신하는 흐름과 구분한다."],["가입 인증 완료","발견 교환만으로 가입 인증이 완료된 것은 아니다."],["응용 데이터 복호화","탐색 프레임 관찰은 사용자 데이터 복호화를 의미하지 않는다."]],'프레임 교환의 역할로 탐색 방식을 구분한다.');
q(w10,discovery,'beacon-role','concept',[12],'Beacon 수신으로 얻을 수 있는 정보의 예는?',2,[["현재 가입자의 모든 응용 데이터 본문","Beacon은 가입자의 응용 내용 전달 프레임이 아니다."],["가입 인증 교환 전체와 그 성공 결과","발견 정보만으로 개별 단말의 가입 교환과 완료를 알 수 없다."],["네트워크 존재·지원 능력·시간 관련 정보","Beacon은 발견과 동기화 등에 필요한 정보를 알린다."],["상위 인터넷 회선의 현재 도달성과 속도 보장","Beacon 수신은 상위 인터넷 경로의 정상 동작을 보증하지 않는다."]],'Beacon은 발견과 동기화에 도움이 되는 관리 정보이며 사용자 인증 자료를 대신하지 않는다.');
q(w10,discovery,'map-not-permission','application',[15,16,17,18],'역사적 무선 지도에 AP 위치가 표시되어 있다. 이를 해석하는 올바른 태도는?',1,[["지도에 표시된 AP는 모두 공개 접속을 허용한 것이다","발견·공개 표시가 이용 승인을 뜻하지 않는다."],["특정 조건에서 발견된 위치 단서이며 사용 허가는 별개다","관찰 결과의 위치 단서와 소유자의 이용 승인을 구분한다."],["과거 위치 표시는 현재 신호와 장치 운영을 보장한다","측정 시점과 환경 변화가 있어 현재 상태는 새로 확인해야 한다."],["지도에 없으면 해당 위치에 무선 장치가 전혀 없다","관찰 누락과 조사 범위의 한계가 있을 수 있다."]],'발견·표시·접속·복호화는 서로 다른 단계의 주장이다.');
q(w10,discovery,'hidden-ssid','application',[13],'SSID를 숨기면 별도 인증이나 암호화 없이도 안전하다는 주장의 문제는?',3,[["SSID를 숨기면 프레임 전체에 자동 암호화가 적용돼서 안전하다","이름 광고 설정과 프레임 내용 암호화는 다른 기능이다."],["숨긴 이름을 아는 것 자체가 장치의 강한 신원 증명이어서 안전하다","네트워크 이름은 강한 비밀 자격증명이나 장치 인증을 대신하지 못한다."],["일반 목록에서 안 보이면 수동·능동 관찰 모두에서 네트워크가 사라져서 안전하다","발견 편의의 변화가 모든 관찰 가능성의 제거는 아니다."],["이름 숨김이 무선 통신의 모든 흔적이나 내용 노출을 제거하지 못해서","SSID 노출을 줄이는 설정은 가입 인증이나 내용 암호화를 대신하지 않는다."]],'이름 표시를 줄여도 적절한 가입 인증·암호화가 필요하다.');
q(w10,discovery,'war-terms','contrast',[13,15,16,17],'WarWalking·WarDriving·WarChalking의 역사적 구분으로 옳은 것은?',0,[["앞의 둘은 이동 방식, 마지막은 발견 정보를 기호로 표기하는 행위다","역사적 용어에서 이동 관찰 방식과 발견 정보 표기를 구분한다."],["세 용어는 각각 도보·차량·자전거라는 이동 수단만 구분한다","WarChalking은 이동 수단이 아니라 발견 정보를 표기하는 행위다."],["앞의 둘은 정보 표기 방식이고 마지막만 차량 이동 관찰이다","이동 관찰과 기호 표기의 구분을 뒤바꿨다."],["세 용어는 각각 수동 탐색·능동 탐색·가입 인증이라는 프로토콜 단계를 뜻한다","역사적 관찰 활동의 명칭과 무선 프로토콜 단계는 구분해야 한다."]],'명칭을 실행 절차로 익히기보다 발견·표시의 의미와 권한 한계를 이해한다.');

const radio = objective(w10,'radio','채널·안테나·모니터 모드의 관찰 한계',[13,14,21,22],
  '도구 화면에 패킷이 없다고 통신이 없다는 결론을 내리면 관찰 장비의 한계를 사실로 오해하게 된다.',
  ['안테나의 지향성은 어느 방향으로 신호를 더 잘 송수신하는지를, 이득은 같은 조건에서 특정 방향의 상대적 집중을 설명한다. 지향성 안테나가 새 에너지를 만들어 모든 방향의 통신을 동시에 강화하는 것은 아니다. 불필요한 방향의 방사와 주변 간섭, 수신 위치·거리도 실제 관찰에 영향을 준다. 교안의 구형 AP 탐지 도구와 카드 모델은 역사적 예시이며 현재 호환성을 보증하지 않는다.',
   'RFMON 또는 모니터 모드는 지원하는 장치·드라이버가 수신한 802.11 프레임을 관찰하도록 하는 성질이다. 일반적인 단일 무선 장치는 선택한 채널에 묶이고, 채널 순회는 각 채널을 순차 관찰하므로 틈을 만든다. 모든 채널을 동시에 듣거나 자기 패킷만 수집한다는 단정은 모두 부정확하다. 송신·동시 접속 가능성 역시 구현에 의존하므로 모드 이름만으로 영구 수신 전용이라 일반화하지 않는다.'],
  '관찰 장치·채널·시각·수신 환경을 함께 기록해야 무응답의 뜻을 해석할 수 있다.',
  [['지향성','특정 방향에 대한 송수신 특성','한 방향 관찰에 더 유리한 안테나'],['채널','관찰하는 주파수 구간','단일 채널 기록에서 다른 채널 통신 누락'],['모니터 모드','수신한 무선 프레임 관찰 지원','관리 프레임을 포함한 가상 분석 자료']],
  '가상 관찰기가 채널 A만 보고 있으며 대상 AP는 채널 B에 있다.',
  ['장치가 현재 어떤 채널을 관찰하는지 확인한다.','현재 기록에 프레임이 없다는 사실을 무선망 부재와 구별한다.'],
  '관찰 범위 밖 통신은 기록 누락일 수 있다.',
  '모니터 모드가 모든 채널을 동시에 무제한 수신한다는 생각은 물리적 수신 범위를 지운다.',
  '채널을 빠르게 순회하면 관찰의 어떤 한계가 남는가?', '다른 채널을 보는 시간 동안 현재 채널의 사건을 놓칠 수 있으므로 동시 전수 관찰이 아니다.', ['monitor-limits']);
q(w10,radio,'channel-blindspot','evidence',[13,21,22],'가상 관찰기는 채널 A, 확인하려는 AP는 채널 B다. 프레임이 없는 기록의 타당한 해석은?',2,[["대상 AP가 어떤 채널에서도 프레임을 송신하지 않았다","채널 A의 기록만으로 채널 B의 송신을 배제할 수 없다."],["채널만 다르면 AP가 반드시 암호화 비밀번호를 변경한 것이다","채널 조건과 비밀번호 변경은 별개다."],["관찰 채널 차이로 누락되었을 수 있다","수신 대상 채널을 관찰하지 않았다면 부재 기록으로 송신 부재를 단정하기 어렵다."],["프레임이 없으므로 무선 침입이 확정되었다","관찰 누락은 침입의 충분한 증거가 아니다."]],'관찰 조건을 먼저 확인해야 부재 추론을 할 수 있다.');
q(w10,radio,'antenna-gain','concept',[14],'지향성 안테나의 이득을 가장 적절하게 설명한 것은?',1,[["모든 방향의 수신 범위가 같은 비율로 늘어남을 뜻한다","방향성 집중과 전방향의 동일한 성능 증가는 다르다."],["특정 방향의 송수신 특성 집중을 나타낸다","방향성 이득은 모든 방향에서 동일한 범위 증가를 뜻하지 않는다."],["송신기 자체의 출력 전력이 그 값만큼 증가함을 뜻한다","안테나의 방향 특성과 송신기 출력 전력 자체를 구분해야 한다."],["장애물과 설치 방향에 관계없이 일정한 수신 거리를 보장한다","실제 수신은 방향·주변 환경·장치 조건에도 영향을 받는다."]],'방향 특성은 범위·간섭에 영향을 주지만 허가나 암호 해독을 제공하지 않는다.');
q(w10,radio,'monitor-driver','application',[21,22],'같은 운영체제라도 무선 카드마다 모니터 관찰 가능 범위가 다른 이유는?',0,[["장치·드라이버의 지원 기능이 다를 수 있어서","같은 OS라도 하드웨어와 드라이버가 제공하는 관찰 기능이 다를 수 있다."],["운영체제 이름만 같으면 모든 카드의 관찰 모드도 같아서","장치·드라이버 지원 차이를 무시한 주장이다."],["암호화 비밀번호를 알면 카드의 모든 관찰 모드가 자동 추가돼서","비밀키 보유와 장치의 프레임 수신 기능 지원은 별개다."],["관찰 채널만 일치하면 드라이버 지원 여부는 무관해서","채널 일치는 필요 조건의 일부일 뿐 기능 지원을 대신하지 않는다."]],'모드 이름만으로 모든 환경의 관찰·송신 능력을 단정하지 않는다.');
q(w10,radio,'channel-hopping-gaps','contrast',[13,21],'단일 무선 장치가 채널을 순회하여 기록할 때 남는 한계는?',3,[["한 번 순회하면 여러 채널의 같은 시각을 동시에 관찰한 자료가 된다","장치가 각 채널에 머문 시각이 다르므로 동시 관찰이 아니다."],["순회 간격을 줄이면 채널 전환 시간의 누락도 완전히 없어진다","관찰 공백을 줄일 수 있어도 완전한 동시 관찰을 보장하지 않는다."],["기록에 프레임이 없으면 채널 체류 시간과 무관하게 대상 부재가 증명된다","부재 판단에는 해당 채널을 실제 관찰한 시간도 중요하다."],["한 채널을 떠난 시간의 프레임을 놓칠 수 있다","채널 순회는 여러 채널을 훑지만 모든 채널을 동시에 완전 관찰하지는 않는다."]],'관찰 범위를 넓혀도 시간별 전수 기록을 보증하지는 않는다.');
q(w10,radio,'legacy-tool-compatibility','evidence',[14,21],'교안의 구형 PDA·무선 칩셋·탐지 도구 목록을 현재 장비 호환성 증거로 써도 되는가?',1,[["예, 칩셋 계열 이름이 비슷하면 모든 현재 드라이버도 같다","제품명 유사성은 기능 호환성을 보증하지 않는다."],["아니오, 역사적 예시이고 현재 지원은 별도 확인해야 한다","기기·OS·드라이버·버전별로 실제 지원 조건을 확인해야 한다."],["예, 구형 도구가 한 OS에서 실행되었으면 현재 모든 OS에서도 실행된다","실행 환경과 지원 버전이 달라질 수 있다."],["아니오, 오래된 관찰 개념은 현재 교육에도 전혀 사용할 수 없다","역사적 개념 학습과 현재 장비 호환성 주장은 구분할 수 있다."]],'교안의 장비 이름은 원리의 배경이며 설치·실행 활동으로 확장하지 않는다.');

const mac = objective(w10,'mac-filter','MAC 필터는 왜 강한 사용자 인증이 아닌가',[19,20],
  '승인 목록에 있는 주소가 보였다는 이유만으로 정당한 단말과 사용자라고 믿으면 주소 복제를 구분하기 어렵다.',
  ['MAC 주소 필터는 프레임에 표시된 주소를 허용 목록과 비교한다. 주소는 통신 식별에 필요하지만 비밀 자격증명이 아니며 장치·운영체제 설정에 따라 변경될 수 있다. 따라서 알려진 주소가 나타났다는 사실은 그 주소를 원래 사용하던 물리 장치나 사용자의 신원을 암호학적으로 증명하지 않는다.',
   '교안은 허용 주소 관찰 뒤 주소를 바꾸는 흐름을 제시하지만 학습 앱에서는 명령·도구 사용 절차를 제공하지 않는다. 가상 중복 주소 로그로 주소 신뢰의 한계를 분석한다. 주소 변경은 프라이버시 목적의 무작위화 등 정당한 경우도 있어 변경 자체로 공격을 단정할 수 없다. 가입 인증·암호화·장치 관리와 내부 자원 인가를 결합하고 이상 주소는 정당한 변경 기록과 대조한다.'],
  '공개 식별자의 일치는 비밀이나 장치 소유 증명이 아니다.',
  [['MAC 허용 목록','주소 문자열의 일치 검사','허용 주소면 접속 조건 일부 충족'],['암호학적 가입 인증','자격증명·키 통제의 검증','정당한 가입 주체인지 검증']],
  '가상 로그에서 같은 주소가 서로 다른 위치에서 거의 동시에 나타난다.',
  ['주소 일치만으로 같은 단말이라고 확정하지 않고 중복·변경 가능성을 적는다.','인증 세션·장치 관리 기록과 비교하여 정당한 변경인지 조사한다.'],
  '주소는 단서이지만 독립 인증 증거로 충분하지 않다.',
  'MAC은 공장에서 정해지므로 절대 바뀌지 않는다는 생각은 설정 가능한 주소와 프라이버시 무작위화를 놓친다.',
  'MAC 필터만 두고 공유 암호·가입 인증을 없애도 되는가?', '안 된다. 주소 문자열은 비밀 증명이 아니므로 필터를 인증의 완전한 대체로 사용할 수 없다.', ['mac-auth']);
q(w10,mac,'mac-not-secret','concept',[19,20],'MAC 필터만으로 강한 인증을 보장하기 어려운 핵심 이유는?',0,[["주소가 비밀 자격증명이 아니고 변경될 수 있어서","허용 주소 확인만으로 실제 장치의 신원을 강하게 입증하지 못한다."],["MAC 필터가 모든 프레임을 암호화해 무결성을 보장해서","주소 허용 목록은 암호화나 메시지 인증 기능이 아니다."],["허용 주소는 하드웨어에서 절대로 변경될 수 없어서","주소를 불변의 비밀 신원으로 취급할 수 없다."],["MAC 필터가 사용자 비밀번호의 강도를 자동 검사해서","주소 목록 검사와 비밀번호 검증은 다른 통제다."]],'주소 허용 목록은 보조 통제이며 정당한 키·사용자 증명을 대신하지 못한다.');
q(w10,mac,'duplicate-mac-log','evidence',[19],'가상 로그에서 같은 MAC이 다른 두 위치에 나타났다. 타당한 후속 판단은?',3,[["같은 MAC이면 두 위치의 사용자는 반드시 한 사람이다","관찰 주소가 사람의 신원을 고유하게 증명하지 않는다."],["서로 다른 위치이면 MAC 위조 공격이 확정된다","중복·위치 추정·기록 시점 등 대안을 조사해야 한다."],["MAC이 일치하므로 가입 인증 기록을 확인할 필요가 없다","주소 일치는 인증 기록의 필요성을 없애지 않는다."],["중복·정당한 변경·관찰 조건을 인증 및 관리 기록과 대조한다","주소 관찰만으로 신원 도용이나 공격 주체를 확정하지 않는다."]],'이상 징후는 조사 출발점이며 단일 식별자로 신원과 의도를 확정하지 않는다.');
q(w10,mac,'privacy-address-change','contrast',[20],'단말의 MAC 주소가 이전 기록과 달라졌다. 공격으로 즉시 확정하면 안 되는 이유는?',1,[["정당한 단말의 MAC은 모든 접속에서 고정되므로 변경 자체가 침입 증거여서","프라이버시 기능 등 정당한 주소 변경이 가능하여 이 전제가 틀리다."],["프라이버시 무작위화 등 정당한 변경도 가능해서","운영체제의 주소 변경 기능과 관리 이력을 함께 확인해야 한다."],["MAC 변경은 항상 하드웨어 교체로만 일어나서","소프트웨어 설정이나 프라이버시 기능으로도 달라질 수 있다."],["새 주소가 허용 목록에 있으면 인증·관리 기록을 대조할 필요가 없어서","주소 허용과 실제 장치·주체 확인은 다른 판단이다."]],'정당한 구성 변경과 악성 행위를 증거로 구분한다.');
q(w10,mac,'layered-wireless-auth','application',[19,20],'MAC 허용 목록을 운영 중인 가상 사무실의 보안 강화 방향은?',2,[["허용 MAC 수를 줄이면 암호화와 사용자 인증을 제거한다","목록 크기는 암호화나 강한 인증을 대신하지 않는다."],["허용 MAC을 가진 장치에는 내부 관리 권한을 모두 준다","네트워크 가입과 자원별 인가는 별개다."],["가입 인증·암호화·장치 관리와 내부 접근 통제를 결합한다","주소 목록을 신원과 내용 보호의 유일한 경계로 두지 않는다."],["SSID를 자주 바꾸면 허용 MAC 목록만으로 충분하다","이름 변경은 주소 위조 가능성과 내용 보호 문제를 해결하지 않는다."]],'하나의 식별자 검사에 신뢰를 집중하지 않는 설계다.');
q(w10,mac,'ap-address-identity','application',[19,25,26],'가상 관리 표에서 BSSID와 SSID를 구분해야 하는 이유는?',0,[["BSSID는 기본 서비스 집합 식별자이고 SSID는 네트워크 이름이어서","같은 SSID를 제공하는 여러 BSS를 관리할 때 구분이 필요하다."],["SSID가 같으면 BSSID와 관리 주체도 항상 같다","네트워크 이름 일치만으로 집합 식별자나 운영자가 같다고 할 수 없다."],["BSSID가 바뀌면 SSID도 반드시 바뀌므로 이름만으로 각 집합을 구분할 수 있어서","같은 SSID 아래 서로 다른 BSS를 구분하려면 BSSID를 함께 보아야 한다."],["SSID 하나에는 물리적 AP가 반드시 하나만 존재해서","같은 이름을 여러 AP가 제공하는 구성이 가능하다."]],'관찰 화면의 필드 이름을 사용자 신원이나 비밀값과 혼동하지 않는다.');

const wep = objective(w10,'wep','WEP의 프레임 구조가 약점을 만드는 이유',[23,24,25,26,27,28],
  '키 길이 숫자만 늘려도 설계상의 반복과 무결성 약점이 해결되는 것은 아니다.',
  ['역사적 WEP는 RC4 키스트림과 평문·ICV의 XOR로 데이터 부분을 보호했다. ICV는 데이터의 CRC-32이며 평문 데이터와 함께 암호화되고, IV와 KeyID는 평문으로 전달된다. MAC 헤더 전체가 비밀이 되는 방식은 아니다. 흔히 말하는 64비트 WEP는 비밀 부분 40비트와 공개 IV 24비트의 조합이므로 비밀 엔트로피 64비트라고 세면 안 된다. 128비트라는 이름도 104비트 비밀과 24비트 IV의 조합을 뜻한다.',
   '같은 비밀키와 같은 IV를 다시 쓰면 같은 RC4 입력으로 같은 키스트림 S가 만들어진다. 같은 위치·같은 길이의 평문 구간을 P1과 P2, 대응 암호문을 C1과 C2라 하면 C1 = P1 XOR S, C2 = P2 XOR S다. 두 암호문을 XOR하면 같은 S가 상쇄되어 C1 XOR C2 = P1 XOR P2가 된다. XOR는 비트별로 다르면 1, 같으면 0이 되는 연산이라 같은 보호 마스크를 두 번 적용한 효과가 사라진다. 따라서 암호문만으로도 평문 사이의 관계가 드러나고 한쪽 구간을 알고 있으면 다른 쪽 같은 구간을 유추할 수 있다. 같은 IV라도 비밀키가 다르거나 같은 키라도 IV가 다르면 이 동일 입력 재사용 조건을 그대로 적용할 수 없다. 이것이 다른 조합의 안전성을 보증한다는 뜻은 아니다.',
   '이 관계 노출은 비밀키를 즉시 복구했다는 뜻이 아니다. 두 평문을 모두 자동으로 얻는다는 뜻도 아니며 키 복구에는 별도 분석과 조건이 필요하다. 짧은 IV 공간과 RC4 구성 약점이 위험을 키우지만 패킷 수가 일정 개수에 도달하면 반드시 일정 시간 안에 복구된다는 법칙은 없다. CRC-32는 우발적 오류 검출용이며 키를 가진 송신자의 진정성을 증명하는 강한 인증 코드도 아니다. 교안의 수집·재전송·복구 도구 화면은 역사적 증거 해석으로만 다루며 현재 보호 수단으로 WEP를 선택하지 않는다. NIST SP 800-97은 역사적 구조 확인용이고 2025년에 철회되어 현재 운영 지침으로 제시하지 않는다.'],
  '공개 IV를 비밀 키 길이에 더해 강도를 판단하지 말고 알고리즘의 반복·무결성 설계까지 살핀다.',
  [['IV·KeyID','복호화에 필요한 공개 부가 정보','프레임 앞의 공개 필드'],['Data·ICV','키스트림으로 보호되는 부분','데이터와 CRC-32가 함께 암호화'],['CRC와 인증 코드','오류 검출과 악의적 변조 방지는 다름','CRC 일치만으로 송신자를 인증하지 못함']],
  '실제 WEP 키·프레임이 아닌 4비트 개념 모형이다. 같은 비밀키와 같은 IV가 만든 마스크를 S=1010, 두 평문 구간을 P1=0011과 P2=0101로 가정한다.',
  ['같은 키·같은 IV의 재사용 조건을 먼저 확인한다. 개념 모형의 C1은 0011 XOR 1010 = 1001, C2는 0101 XOR 1010 = 1111이 된다. 실제 WEP 키나 IV 길이가 4비트라는 뜻은 아니다.','C1 XOR C2를 계산하면 0110이고 P1 XOR P2도 0110이다. 같은 마스크가 상쇄되어 두 평문 사이의 관계가 남는 이유를 설명한다.','다른 키에 같은 IV를 쓰거나 같은 키에 다른 IV를 쓴 예는 동일 입력 반복으로 단정하지 않는다. 여기서는 평문 관계가 드러났을 뿐 실제 비밀키 획득이나 모든 평문 복구를 입증하지 못했다고 기록한다.'],
  '재사용의 위험은 단순한 키 길이가 아니라 반복 마스크가 상쇄되는 구조에서 온다. 다른 조합도 안전하다고 선언하지 않으며 WEP 대신 지원되는 현대 보호 구성으로 전환한다.',
  'IV가 공개이니 모든 현대 암호도 실패한다는 생각은 공개 nonce를 안전하게 설계하는 방식과 WEP의 결함을 혼동한다.',
  'CRC가 맞는다는 사실이 정당한 송신자의 메시지임을 증명하는가?', '아니다. CRC는 비밀키 기반 인증 증명이 아니므로 악의적 변조에 대한 강한 무결성을 대신하지 못한다.', ['wep-structure','iv-count','wep-integrity']);
q(w10,wep,'wep-secret-bits','application',[23,24],'역사적 WEP-64의 조합이 비밀 40비트와 공개 IV 24비트라면 비밀 부분은?',2,[["64비트","공개 IV까지 합친 표시 길이를 모두 비밀 정보로 센 것이다."],["24비트","이 수치는 공개 IV 길이이며 비밀 부분 길이가 아니다."],["40비트","공개 IV 24비트를 64에서 제외한 비밀 부분의 길이다."],["104비트","역사적 WEP-128의 비밀 부분과 WEP-64를 혼동했다."]],'표시 길이가 곧 비밀 엔트로피를 뜻하지 않는다. 이 계산은 WEP 구조에 한정한다.');
q(w10,wep,'wep-encrypted-fields','contrast',[23,24],'역사적 WEP 프레임에서 암호화되는 부분의 조합은?',0,[["데이터와 그 ICV","역사적 WEP에서는 데이터 뒤의 ICV도 키스트림으로 보호되는 부분에 들어간다."],["공개 IV와 Key ID만","수신 측이 처리에 쓰는 공개 필드를 암호화 대상과 뒤바꾸었다."],["데이터만이며 ICV는 항상 평문으로 남는다","WEP 구성에서 ICV도 데이터와 함께 암호화된다."],["전체 MAC 헤더와 공개 IV를 포함한 프레임 전부","무선 프레임 전체를 같은 방식으로 숨기는 구성이 아니다."]],'WEP 프레임 그림은 보호되는 부분과 공개되는 부분의 경계를 보여 준다.');
q(w10,wep,'crc-vs-authenticator','concept',[24],'WEP의 CRC-32 ICV가 강한 메시지 인증 코드와 다른 이유는?',3,[["WEP의 ICV가 암호화되지 않아 공개되는 것만이 유일한 원인이어서","ICV는 데이터와 함께 암호화된다. 핵심은 CRC가 키 기반 인증 코드로 설계되지 않았다는 점이다."],["ICV가 암호화되어 있으면 CRC도 자동으로 강한 인증 코드가 되어서","검사값을 암호화했다는 사실만으로 악의적 변조 저항성이 보장되지 않는다."],["CRC가 비밀번호 길이를 검증하므로 키를 길게 하면 인증 기능도 생겨서","CRC는 데이터의 오류 검출용이며 비밀번호 강도 검사나 비밀키 인증 기능이 아니다."],["비밀키 기반 악의적 변조 방지 증명을 제공하도록 설계된 코드가 아니어서","CRC는 우발적 오류 검출용이며 암호화와 결합했다고 강한 인증 코드가 되지 않는다."]],'CRC 일치만으로 악의적 변경이나 송신자 위장을 배제할 수 없다.');
q(w10,wep,"wep-same-key-iv","application",[23,24],"가상 WEP 표의 키 표시는 실제 비밀키의 구분이고 IV 표시는 전체 IV를 줄여 쓴 식별자다. 동일 입력으로 키스트림이 재사용되는 쌍은?",1,[["A와 C","IV는 같지만 비밀키가 다르므로 같은 키스트림 재사용을 이 표만으로 단정할 수 없다."],["A와 B","같은 비밀키 K1과 같은 IV 01이 함께 반복되어 키스트림 재사용 조건이 된다."],["A와 D","비밀키는 같지만 IV가 달라 해당 동일 입력 재사용 조건에 해당하지 않는다."],["C와 D","비밀키와 IV가 모두 달라 같은 조합의 반복이 아니다."]],"A와 B는 같은 비밀키와 같은 IV를 사용한다. 반복 키스트림의 XOR가 상쇄되면 평문 사이의 관계가 드러날 수 있지만, 이 관찰만으로 비밀키를 즉시 복구했다고 결론 내리는 것은 아니다. 같은 IV만 있거나 같은 키만 있다는 조건은 이 표의 동일 입력 재사용 조건과 다르다.","모두 같은 WEP 방식의 가상 기록이다. 실제 키나 프레임 자료가 아니다.\n프레임 | 비밀키 구분 | 전체 IV 식별자\nA | K1 | 01\nB | K1 | 01\nC | K2 | 01\nD | K1 | 02");
q(w10,wep,'longer-wep-not-remedy','application',[24,27],'가상 관리자가 WEP 키 표시 길이만 늘리면 계속 안전하게 쓸 수 있다고 제안한다. 적절한 평가는?',0,[["IV·무결성·알고리즘 구성 약점이 남으므로 현대 보호 구성으로 전환한다","비밀 부분 길이 증가만으로 프로토콜의 구조적 약점을 없앨 수 없다."],["표시 길이가 길어지면 공개 IV도 비밀키로 바뀌므로 계속 사용한다","키 길이 표시는 공개 IV를 비밀로 만들지 않는다."],["주소 필터만 추가하면 WEP 무결성 약점도 제거된다","주소 통제는 암호 프로토콜의 무결성을 고치지 않는다."],["비밀번호를 주기적으로 바꾸면 WEP가 현대 방식과 동등해진다","운영 변경이 구형 암호 구성 자체를 현대 방식으로 대체하지 않는다."]],'역사적 WEP의 결함을 길이 숫자 하나로 해결한다고 보지 않는다.');

const keyexchange = objective(w10,'keys-wpa','키 분배와 WPA 세대의 조건',[23,27],
  '공개키가 있다고 상대의 신원이 자동 확인되는 것도, 인증 교환을 봤다고 암호를 바로 얻는 것도 아니다.',
  ['대칭키 암호는 공유 비밀로 많은 데이터를 효율적으로 보호하지만 비밀을 안전하게 공유·관리해야 한다. 공개키 방식은 공개·개인 키의 역할을 나누어 키 합의나 서명 등에도 쓰이나 공개키가 누구의 것인지 검증하는 문제는 남는다. 공개키 방식이면 키 교환 문제가 전혀 없다거나 항상 대칭키보다 정확히 천 배 느리다는 표현은 알고리즘·구현·목적의 차이를 무시한다.',
   '교안의 WPA-PSK 사례는 WPA/WPA2-Personal의 약한 암호구를 관찰된 인증 교환과 후보로 검증할 수 있는 역사적 조건을 설명한다. Handshake가 비밀번호 원문을 전송하는 것은 아니며 충분한 자료가 있어도 강한 무작위 암호구의 복구가 보장되지 않는다. 현대 보충: WPA3-Personal의 SAE는 수동 수집만으로 같은 방식의 오프라인 사전 대입을 하기 어렵게 설계되었다. WPA3라는 이름만으로 전환 모드·구현 결함·약한 암호·AP 관리 문제가 모두 사라지는 것은 아니다.'],
  '세대·인증 방식·암호구 강도·실제 구현 조건을 붙여 주장을 해석한다.',
  [['대칭키','공유 비밀로 데이터 보호','통신 내용을 빠르게 보호'],['공개키','공개·개인 키 역할을 구분','상대 키의 진정성을 검증하며 합의'],['WPA2-Personal과 WPA3-SAE','인증 교환과 추측 저항성 설계가 다름','현대 SAE 보충을 과거 PSK 예와 구분']],
  '가상 보고서가 인증 교환을 보았으니 WPA 암호가 모두 노출되었다고 썼다.',
  ['비밀번호 원문 관찰인지, 특정 방식에서 후보를 검증할 자료인지 분리한다.','WPA 세대·인증 방식·암호구·구현·추가 암호화 계층을 확인해 결론 범위를 정한다.'],
  '교환 관찰만으로 원문 복구나 모든 통신 해독을 확정하지 않는다.',
  '공개키를 받으면 무조건 진짜 상대라는 생각은 키와 신원의 연결을 검증하는 문제를 빠뜨린다.',
  'WPA3-SAE 설명을 구형 WPA-PSK 사전 대입과 구별해야 하는 이유는?', '인증 교환의 구조와 오프라인 추측에 대한 설계 목표가 달라 구형 조건을 세대 전체에 일반화할 수 없기 때문이다.', ['public-key-context','wpa-generations']);
q(w10,keyexchange,'public-key-authenticity','concept',[23],'공개키 방식에서도 여전히 필요한 검증은?',1,[["공개키를 비공개로 숨겼으므로 소유자 검증을 생략한다","공개키의 공개 여부와 신뢰할 수 있는 신원 연결은 별개다."],["받은 공개키가 의도한 상대와 연결되는지","키의 소유 주체를 검증해야 잘못된 상대의 키를 신뢰하는 일을 줄인다."],["키 길이가 충분히 길면 소유자도 올바르다고 간주한다","충분한 키 길이가 잘못된 상대의 키를 올바른 상대의 것으로 바꾸지는 않는다."],["암호화가 성공하면 상대 신원도 검증된 것으로 간주한다","받은 키로 암호화할 수 있다는 사실만으로 그 키의 소유자가 입증되지 않는다."]],'키 전달 문제의 형태가 바뀌어도 상대 진정성 검증은 남는다.');
q(w10,keyexchange,'handshake-not-password','evidence',[27],'가상 자료에 WPA2-Personal 인증 교환이 보인다. 이 자료만으로 확정할 수 없는 것은?',3,[["인증 교환과 관련된 자료가 관찰되었다","제시된 관찰이 직접 지지하는 제한된 결론이다."],["암호구 선택과 실제 구성의 안전성을 별도 검토해야 한다","관찰 자료만으로 전체 안전성을 확정할 수 없다."],["이 자료를 원문 비밀번호 자체와 구분해야 한다","교환 메시지와 비밀 원문을 구분하는 것이 타당하다."],["비밀번호 원문을 이미 획득했다","인증 교환 관찰과 비밀 원문 획득은 다른 사실이다."]],'관찰된 교환, 후보 검증 가능성, 실제 원문 복구는 서로 다른 주장이다.');
q(w10,keyexchange,'symmetric-role','contrast',[23],'많은 통신 데이터를 공유 비밀로 효율적으로 보호하는 방식은?',0,[["대칭키 방식","공유 비밀을 사용하여 대량의 통신 내용을 효율적으로 보호하는 용도다."],["공개키 암호만으로 모든 대량 데이터를 처리하는 방식","공개키 기능은 유용하지만 질문의 공유 비밀 기반 대량 보호와 구분한다."],["키 합의만 하고 데이터에는 아무 보호를 적용하지 않는 방식","키를 정하는 절차만으로 실제 데이터 기밀성이 생기지 않는다."],["비밀키 없는 해시값만 데이터와 함께 보내는 방식","일반 해시는 데이터를 숨기지 않는다."]],'키 분배 문제와 대량 데이터 보호의 효율을 구별하여 두 암호 방식의 결합을 이해한다.');
q(w10,keyexchange,'sae-vs-psk','contrast',[27],'현대 보충의 WPA3-Personal SAE 설계 목표로 적절한 것은?',2,[["사용자 암호구 선택과 구현 점검이 더는 필요 없게 함","프로토콜 개선이 운영과 구현의 모든 위험을 없애지 않는다."],["모든 온라인 비밀번호 추측을 통신 한 번 없이 차단함","수동 오프라인 추측 저항성과 온라인 시도 대응은 다른 경계다."],["수동 교환 수집만을 이용한 오프라인 사전 추측에 대한 저항성 강화","SAE의 목표를 특정 공격 조건에 한정하며 모든 공격 면제를 뜻하지 않는다."],["가입한 사용자의 모든 응용 권한을 자동 검증함","무선 가입 절차는 응용별 인가를 대신하지 않는다."]],'현대 보충은 설계 목표를 설명하며 전환 구성이나 구현 위험까지 사라진다고 주장하지 않는다.');
q(w10,keyexchange,'strong-passphrase-condition','application',[27],'같은 WPA2-Personal 구성에서 흔한 짧은 암호구보다 충분히 긴 무작위 고유 암호구가 유리한 이유는?',1,[["암호구의 문자 수만큼 무선 데이터 암호키의 비트 수가 계속 늘어서","암호구 선택의 예측 가능성과 프로토콜이 정한 키 표현 길이를 혼동했다."],["공격자가 우선 시도할 예측 가능한 후보에 들어갈 가능성을 줄여서","충분히 긴 무작위 고유 값은 흔한 후보와 재사용 값을 피하는 데 유리하다."],["길이가 한 글자 늘 때마다 추측 비용이 항상 정해진 배수로 증가해서","후보 선택과 분포를 보지 않고 고정 배수로 강도를 판단할 수 없다."],["온라인 로그인 실패 제한이 모든 오프라인 후보 계산까지 중단시켜서","온라인 요청 제한과 이미 확보한 자료의 오프라인 분석은 별개다."]],'암호구 강도 개선은 중요하지만 실제 인증 방식·업데이트·AP 설정도 함께 관리해야 한다.');

correction(w10,'wireless-terms',[1,2,3,28], 'Wi-Fi·무선 인터넷·AP·핫스팟을 혼용하고 과거 이용 장소 그래프를 제시한다.', 'Wi-Fi는 802.11 계열 무선 LAN 맥락이다. 무선 인터넷은 더 넓고 AP 장치와 핫스팟 장소·서비스도 구분한다. 로컬 가입은 인터넷·응용 인증의 보증이 아니다. 과거 그래프의 현재 비중은 미확인이다.', '구조와 연결 단계를 채점하며 현재 통계 순위는 묻지 않는다.', 'contextualized', [R.wlan]);
correction(w10,'incident-facts',[4,5,6], '은행·백화점 국내 사건과 해외 소매업체의 피해 인원·보상액을 단일 수치로 제시한다.', '미 법무부의 2008년 기소 발표는 소매업체 무선 취약점 악용과 4,100만 건 이상 카드 번호 사건을 확인하지만 이를 피해자 수와 동일시하면 안 된다. 국내 사건의 상세 사실·보상액은 이번 확인에서 독립 검증되지 않았다.', '역사적 동기와 방어 원리를 보존한다. 정확한 국내 기관·피해 인원·손실액은 정답으로 쓰지 않는다.', 'contextualized', [R.retail]);
correction(w10,'latte-date',[7], '카페라떼를 2008년 최초 발표, 6~10분의 고정 시간처럼 설명한다.', '발견자 회고는 2007년 연구를 명시한다. 최초 공개 일자·행사까지는 이번 자료로 확정하지 않는다. WEP와 단말 접속 동작에 관련된 역사적 사례이며 성공 시간은 보편 보장이 아니다.', '최초 연도·정확한 분 단위 성공 시간 문제는 제외하고 구형 조건과 설정 관리 교훈만 묻는다.', 'contextualized', [R.latte,R.wep]);
correction(w10,'capture-visibility',[8,21], '패킷 모니터링 동안 모든 사용자 데이터가 노출된다고 표현한다.', '수신 범위·장치·채널 및 암호화에 따라 관찰 내용이 제한된다. 암호문 수집은 곧 평문 해독이 아니다.', '메타데이터 관찰과 내용 노출을 분리하여 채점한다.', 'verified', [R.wlan]);
correction(w10,'beacon-scope',[11,12,13], 'Beacon은 AP에서만 송신, RF 관찰은 모든 채널 데이터 수집처럼 일반화한다.', '교안의 Infrastructure 예에서는 AP가 주기적 공지를 보내지만 다른 802.11 구성까지 AP만 송신한다고 보편화하지 않는다. 탐색과 가입·인터넷 인증은 별개이며 숨긴 SSID는 암호화가 아니다.', 'Infrastructure 예라는 조건을 붙여 탐색 프레임 역할을 묻고 모든 구성에 대한 AP 전용 명제는 채점하지 않는다.', 'contextualized', [R.wlan]);
correction(w10,'monitor-limits',[13,14,21,22,25], 'RFMON을 모든 채널 수신·항상 수신 전용이라고 설명하고 다른 곳에서는 자기 패킷만 수집한다고 적는다.', '일반 단일 장치는 관찰 채널·지원 프레임·드라이버에 제약을 받는다. 모니터는 수신 가능한 다른 단말의 프레임도 관찰할 수 있으나 동시 전 채널 수집은 보장하지 않는다. 송신·동시 접속 특성은 구현별로 다르다. 구형 도구·카드 목록은 현재 호환성 근거가 아니다.', '모드 설정 명령은 제공하지 않고 가상 채널 기록의 누락과 관찰 한계를 묻는다.', 'verified', [R.wlan]);
correction(w10,'mac-auth',[19,20], 'MAC 변경 우회 과정을 설명하며 주소 일치가 신원 증명처럼 오해될 여지가 있다.', 'MAC은 비밀이 아닌 식별자이며 변경·무작위화될 수 있다. 필터는 암호학적 가입 인증을 대체하지 않고 주소 변경만으로 악성을 확정할 수도 없다.', '주소 변경 명령·도구 절차를 가상 중복 로그 해석으로 대체한다.', 'contextualized', [R.wlan,R.wep]);
correction(w10,'public-key-context',[23], '공개키는 키 교환 문제가 없고 대칭키보다 약 1000배 느리다고 고정한다.', '공개키의 진정성·개인키 보호·키 합의의 인증 문제가 남는다. 성능은 알고리즘·목적·구현에 따라 달라 고정 배수가 아니다.', '대칭키·공개키 역할과 신뢰 연결을 묻고 보편 성능 배수는 채점하지 않는다.', 'contextualized', [R.auth,R.wep]);
correction(w10,'wep-structure',[23,24,27], 'WEP의 총 64비트 키와 MAC 프레임 암호화를 비밀 길이·전체 프레임 보호처럼 읽을 수 있다.', 'WEP-40은 비밀 40비트와 공개 IV 24비트의 조합이다. 128비트 표기는 104비트 비밀과 24비트 IV를 포함한다. 데이터와 ICV는 암호화되고 IV·KeyID 및 MAC 헤더는 공개로 남는다.', '정확한 필드·비밀 길이는 역사적 구조로 채점한다. WEP·RC4는 현재 권장 방식으로 제시하지 않는다.', 'verified', [R.wep,R.withdrawn]);
correction(w10,'wep-integrity',[24], 'IV는 언제나 무작위 생성, ICV 불일치는 재전송 요청이라는 일률적 절차를 제시한다.', 'WEP는 IV 생성·변경을 엄밀히 안전하게 강제하지 못했고 짧은 공간·재사용이 위험하다. CRC-32는 강한 메시지 인증이 아니다. NIST의 역사적 설명은 ICV 불일치 프레임 폐기를 기술하므로 별도 명시적 재전송 요청을 보편 단계로 가르치지 않는다.', '오류 검출과 보안 무결성을 구별한다. IV 무작위 강제·불일치 시 요청 메시지 보장은 정답으로 쓰지 않는다.', 'verified', [R.wep]);
correction(w10,'iv-count',[23,24,25,26,27,28], '23~24쪽 IV 기반 구조와 24~28쪽 수집·복구 설명을 읽을 때 같은 IV라는 관찰만으로 재사용이나 고정 복구 성공을 단정할 여지가 있다. 필요 IV 수 표도 서로 다르다.', '같은 비밀키와 같은 IV가 함께 반복되면 같은 키스트림이 재사용된다. 대응 구간의 두 암호문을 XOR할 때 공통 키스트림이 상쇄되어 평문 간 관계가 드러날 수 있지만 비밀키의 즉시 획득은 아니다. 같은 IV·다른 키나 같은 키·다른 IV는 이 동일 입력 조건과 구분한다. 그 구분이 다른 구성의 안전성을 증명하지는 않는다. 관측량·성공은 자료와 모델에 의존하므로 단일 프레임 수나 시간으로 복구를 보장하지 않는다.', '가상 기호와 표로 조건·노출의 범위를 비교한다. 도구·명령·실제 수집이나 키 복구는 제외하고 고정 성공 수치를 채점하지 않는다.', 'contextualized', [R.wep,R.withdrawn]);
correction(w10,'wpa-generations',[27], 'WPA-PSK 교환 수집과 암호구 추측을 모든 WPA 세대의 보편 해독 절차처럼 설명한다.', 'WPA/WPA2-Personal의 약한 암호구 추측 조건과 WPA3-Personal SAE의 설계는 다르다. 교환은 암호 원문이 아니며 강한 암호구 복구·추가 TLS 평문 해독도 자동 보장하지 않는다.', '교안 PSK 사례와 현대 SAE 보충을 명확히 표시한다. 어떠한 실수집·해제·대입 명령도 제공하지 않는다.', 'verified', [R.wpa3,R.wep]);
coverage(w10,[1,2,3], '무선 인터넷·Ad-Hoc/Infrastructure 그림·AP·과거 이용 그래프', [topology]);
