coverage(w10,[8,9], '모니터링·서비스 거부·비인가 AP·가입 통제', [risks]);
coverage(w10,[10,11,12,13], 'AP 탐지 화면·Probe/Beacon·숨김·탐색 유형', [discovery,radio]);
coverage(w10,[14], '안테나 지향성·이득·불필요 방사·구형 도구', [radio], 'historical');
coverage(w10,[15,16,17,18], '도보·차량·기호·무선 지도의 이미지 사례', [discovery], 'historical', '전 페이지 이미지 직접 확인. 사진은 허가·해독 증거가 아니며 원본 이미지는 배포하지 않는다.');
coverage(w10,[19,20], 'MAC 필터의 한계와 주소 변경', [mac], 'covered', '실행 명령 대신 가상 주소·인증 기록 해석.');
coverage(w10,[21,22], '도청 수신 조건·RFMON·캡처 절차의 한계', [radio,risks], 'covered', '수집 실행은 하지 않고 장비·채널·암호화 조건을 학습.');
coverage(w10,[23,24], '대칭/공개키 비교·WEP 프레임·ICV·IV', [wep,keyexchange], 'historical', 'SP 800-97은 철회된 역사적 구조 참고 자료임을 명시.');
coverage(w10,[25,26], '도구 화면 필드·관찰 범위·IV 수 표의 불일치', [wep,mac,radio], 'historical', '명령·대상 주소·실행 절차는 대체하고 필드와 증거 한계만 학습.');
coverage(w10,[27], 'WEP 복구 화면과 WPA-PSK 설명·현대 SAE 보충', [wep,keyexchange], 'historical');
coverage(w10,[28], '학습정리 및 추가 학습요소 표지', [topology,wep], 'covered', 'IV 최대 수집만으로 보편 복구를 보장한다는 요약은 정정. 표지 부분은 행정 요소.');

const w11 = week(11,'웹 보안(1): 요청의 의미와 신뢰 경계',23,
  '브라우저·서버·데이터베이스 사이에서 외부 입력이 어떻게 이동하는지 따라가며 HTTP와 웹 취약점을 연결한다. 교안의 OWASP 목록은 최종 2017판과 다른 역사적 목록으로 표시하고 위험 개념을 빠짐없이 학습한다. 실제 공격 페이로드와 대상은 제공하지 않는다.',
  [R.http,R.http3,R.uri,R.top,R.validation,R.injection,R.xss,R.csrf,R.session,R.authorization,R.storage,R.cern,R.html]);
const methods = objective(w11,'http-methods','HTTP 메소드가 암호화를 뜻하지 않는 이유',[1,2,3,22],
  '민감 데이터를 POST로 옮겼다는 이유만으로 보호됐다고 믿으면 평문 전송·로그 노출·요청 위조를 놓칠 수 있다.',
  ['HTTP는 요청과 응답으로 자원의 표현과 동작을 주고받는 응용 계층 프로토콜이다. HTML뿐 아니라 여러 표현을 운반하며 브라우저 주소창만의 기능도 아니다. 교안의 HTTP/1.0·1.1 연결 비교는 역사적 기본값의 차이로 이해한다. 1.1은 지속 연결을 기본으로 하지만 항상 하나의 연결로 모든 자료를 보낸다는 뜻은 아니다. 현대 보충: HTTP/3는 QUIC을 사용하므로 모든 HTTP가 같은 TCP 연결 모델이라는 일반화도 피한다.',
   'GET은 표현 조회, HEAD는 대응 GET과 유사한 응답 메타데이터를 본문 없이 받는 의미다. POST는 서버가 정한 처리를 요청하고 PUT은 지정 대상의 생성·교체, DELETE는 대상 연결 제거 요청, OPTIONS는 통신 선택사항, TRACE는 진단용 반향 의미를 갖는다. 이 이름 자체가 사용자의 권한이나 실행 허가를 보증하지 않는다. POST 본문은 암호문이 아니며 크기도 서버·중계기 정책으로 제한된다. 전송 보호는 HTTPS, 민감정보 최소화·안전한 로그·서버 검증·인가 등은 별도 통제다.'],
  '메소드의 동작 의미, 전송 암호화, 입력 크기, 사용자 권한을 각각 검증한다.',
  [['GET/HEAD','표현 조회와 본문 없는 메타데이터 조회','문서 내용이 불필요하면 HEAD'],['POST','대상 자원이 정의한 처리 요청','서비스가 접수 후 새 자원의 URI를 정함'],['PUT','클라이언트가 지정한 대상 상태의 생성·대체','알고 있는 문서 URI의 상태를 전송한 표현으로 대체'],['DELETE','대상 URI와 현재 기능의 연결 제거 요청','저장 매체의 모든 복사본 삭제 보장과는 다름'],['OPTIONS/TRACE','통신 옵션 문의와 진단용 요청 루프백','어느 것도 자원 대체나 사용자 인가를 뜻하지 않음'],['HTTPS','전송 보호와 서버 진정성 검증','GET과 POST 모두에 적용 가능']],
  '실제 서버에 요청하지 않는 가상 문서 서비스다. A는 이미 알고 있는 문서 URI를 지정해 상태를 대체하려 하고 B는 접수 서비스가 새 문서 URI를 정하도록 맡긴다.',
  ['A는 대상 URI를 클라이언트가 지정하고 전송한 표현으로 상태를 생성·대체하려 하므로 PUT의 의미와 연결한다. B는 대상 서비스의 처리를 요청하고 서비스가 URI를 정하므로 POST와 연결한다.','내용 없이 조회 메타데이터만 필요하면 HEAD, 통신 옵션을 묻는 목적이면 OPTIONS로 구분한다. TRACE는 진단용 루프백으로 자원 저장이나 인가 검사가 아니다.','DELETE의 연결 제거 의미를 저장소 전체의 물리 삭제 보장과 구분한다. 어느 메소드든 실제 지원 여부와 사용자 권한을 확인하고 HTTPS·크기 제한·로그 정책을 별도 적용한다.'],
  '메소드는 요청 의도를 표현한다. 실제 지원·인가·전송 보호·저장 구현은 이름만으로 보장되지 않는다.',
  'POST라면 안전하다는 생각은 URL 표시를 줄이는 것과 기밀성·인가를 혼동한다.',
  'HTTPS GET과 평문 HTTP POST 중 메소드 이름만으로 안전성을 비교할 수 있는가?', '아니다. 전송 보호 여부가 다르며 두 경우 모두 민감 값의 URL·로그 기록과 권한 통제를 별도로 검토해야 한다.', ['post-security','http-version']);
q(w11,methods,'post-not-encryption','application',[2,3],'가상 로그인 폼이 HTTP POST를 쓴다는 이유만으로 전송 기밀성을 주장한다. 가장 정확한 평가는?',1,[["본문은 주소창에 없으므로 일반 HTTP에서도 기밀성이 보장된다","주소창 표시와 네트워크 구간의 기밀성은 다르다."],["POST 본문도 전송 보호가 없으면 노출될 수 있어 HTTPS가 필요하다","POST는 메소드 의미이며 본문을 암호화하는 전송 보호가 아니다."],["GET을 POST로 바꾸면 TLS 인증서 검증을 생략할 수 있다","요청 메소드와 서버 인증·전송 보호는 별개다."],["POST 본문은 서버에서도 읽을 수 없어 비밀번호 처리가 불가능하다","수신 서버의 처리와 전송 중 도청 방지는 구분해야 한다."]],'POST는 데이터 처리 의미이며 암호화는 HTTPS 등 별도 보호다.');
q(w11,methods,'head-body','concept',[2],'문서 본문을 받지 않고 대응 GET의 메타데이터를 확인하려는 가상 요청에 맞는 메소드는?',2,[["GET","일반 GET은 응답 내용을 전달하는 의미이므로 본문 없이 메타데이터만 받으려는 목적과 다르다."],["OPTIONS","대상과 관련한 통신 옵션을 문의하는 메소드로 HEAD와 구분한다."],["HEAD","GET과 같은 의미의 메타데이터를 요청하되 응답 내용은 받지 않는 메소드다."],["TRACE","요청 메시지의 진단용 루프백을 위한 메소드이며 문서 메타데이터 조회 목적이 아니다."]],'본문이 불필요한 조회와 자원 변경 요청을 구별한다.');
q(w11,methods,"put-target-replacement","application",[2],"가상 문서 서비스에서 클라이언트가 대상 URI를 이미 알고 있으며, 지정한 문서 상태를 전송한 표현으로 생성·대체하려 한다. 이 의도에 가장 맞는 HTTP 메소드는?",0,[["PUT","클라이언트가 지정한 대상 URI의 상태를 전송한 표현으로 생성·대체하는 의도에 맞는다."],["POST","대상 자원이 정의한 처리를 요청하는 일반 의미이며 지정 URI의 생성·대체와 구분한다."],["OPTIONS","통신 옵션에 대한 정보 요청이지 자원 상태 대체가 아니다."],["DELETE","대상 URI와 현재 기능의 연결 제거를 요청하는 의미이지 전송한 표현으로 대체하는 의미가 아니다."]],"PUT은 클라이언트가 지정한 대상 자원의 상태를 전송한 표현으로 생성·대체하려는 의미다. POST는 대상이 정의한 처리, OPTIONS는 통신 옵션 문의, DELETE는 대상 URI와 현재 기능의 연결 제거 요청이다. 메소드 선택 자체가 변경 권한을 부여하지 않으므로 서버 인가와 전송 보호는 별도로 필요하다.");
q(w11,methods,'post-body-limit','evidence',[2],'가상 서비스가 POST 본문이 크다는 이유로 413을 반환했다. 옳은 설명은?',3,[["413은 해당 서버가 POST 메소드 자체를 모른다는 뜻이다","내용 크기 거부와 메소드 미지원은 다른 의미다."],["413은 사용자의 변경 권한이 부족하다는 확정 응답이다","권한 거부가 아니라 요청 내용이 처리하려는 크기보다 큼을 나타낸다."],["413을 받으면 같은 본문을 GET으로 옮길 때 제한이 사라진다","메소드 변경으로 서버·중계기의 크기 한계가 자동 제거되지 않는다."],["서버·중계기의 허용 크기를 넘었을 수 있다","POST라는 사실이 배포 구성의 본문 크기 제한을 제거하지 않는다."]],'메소드별 의미가 자원 한계를 제거하지는 않는다.');

const urls = objective(w11,'url-status','URL과 상태 코드로 알 수 있는 범위',[4,5],
  '오류 코드 하나로 취약점이나 공격 성공을 확정하면 원인 분석이 잘못된다. 요청 위치와 처리 결과의 의미를 구분한다.',
  ['URL은 스킴, 호스트·포트, 경로, 질의, 조각 식별자 등의 구조를 가진다. 질의에서 이름과 값을 구분하는 관례를 이해하되 문자를 인코딩하는 것은 암호화가 아니다. 퍼센트 인코딩은 바이트를 표기하는 방식이고, 플러스의 공백 해석은 폼 인코딩 문맥에 해당한다. 조각 식별자는 HTTP 요청 대상에 그대로 포함되어 서버로 보내지는 부분이 아니다. 교안의 물결표 홈 경로·골뱅이 해석도 모든 URL의 일반 법칙은 아니다.',
   '응답 상태는 처리 결과의 분류다. 200은 요청 성공, 201은 새 자원 생성으로 POST와 PUT 등에서 나올 수 있다. 400은 잘못된 요청, 401은 유효한 인증 정보 부족과 인증 요구, 403은 요청 거부, 500은 서버의 예상 밖 오류를 나타낸다. 500만으로 SQL 인젝션이 존재하거나 성공했다고 확정할 수 없고, 200만으로 업무상 성공·민감 자료 노출까지 보증하지 않는다. 응답 본문과 서버 기록을 함께 읽는다.'],
  '표현 방식과 비밀 보호를 구별하고 상태 코드에 맞는 범위로만 결론을 낸다.',
  [['질의와 조각','서버 처리 매개변수와 표현 내 위치의 차이','검색 조건과 문서 내부 위치'],['201과 200','자원 생성과 일반 성공 의미 구분','신규 접수 생성과 기존 자료 조회'],['401과 500','인증 정보 문제와 서버 오류 구분','로그인 요구와 처리 실패']],
  '가상 접수 서비스가 POST 처리 뒤 201을 반환했다.',
  ['201이 새 자원 생성 의미인지 확인하고 POST라는 이유로 규격 오류라 판단하지 않는다.','Location 등 응답 정보와 실제 업무 결과를 확인하며 상태 코드만으로 저장·권한 전체를 확정하지 않는다.'],
  '201은 PUT 전용 코드가 아니며 처리 의미와 결과 증거를 함께 본다.',
  '퍼센트 인코딩으로 바꾸면 비밀 값이 보호된다는 생각은 표기 변환과 암호화를 혼동한다.',
  '서버가 500을 반환했다는 사실만으로 SQL 인젝션을 확정할 수 있는가?', '아니다. 다양한 오류가 같은 코드를 만들 수 있으므로 입력 경로·질의 구성·권한과 내부 진단 근거가 필요하다.', ['http-status','url-context']);
q(w11,urls,'created-post','concept',[4],'새 자원을 만든 가상 POST 요청에 201 Created가 반환되었다. 정확한 해석은?',0,[["생성 의미에 맞는 응답일 수 있다","요청 결과 자원이 생성된 경우 201은 적합한 상태 코드다."],["POST는 반드시 200만 반환하므로 프로토콜 위반이다","메소드별 응답이 200 하나로 고정되어 있지 않다."],["201은 요청이 접수만 되었고 처리가 완료되지 않았음을 뜻한다","접수 후 미완료를 뜻하는 202와 생성 결과인 201을 혼동했다."],["201이면 모든 후속 요청에도 생성 권한이 자동 부여된다","한 요청의 결과와 후속 요청 인가는 별개다."]],'201은 새 자원 생성의 의미로 이해한다.');
q(w11,urls,'500-not-sqli','evidence',[4],'가상 입력 뒤 500이 나왔다. 확정할 수 없는 것은?',2,[["해당 요청에서 서버 오류 응답이 발생했다","관찰된 상태 코드가 직접 지지하는 결론이다."],["서버 기록에서 오류 원인을 추가로 조사할 필요가 있다","원인과 영향 판단에 필요한 타당한 후속 과제다."],["SQL 인젝션이 성공했다","예상 못한 서버 오류만으로 구체적인 공격 원인과 성공을 확정할 수 없다."],["오류 응답과 실제 데이터 변경 여부를 구분해야 한다","실패 표시와 공격 영향은 별도 근거로 판단해야 한다."]],'오류 관찰을 특정 취약점·침해 성공으로 확대하지 않는다.');
q(w11,urls,'encoding-not-encryption','contrast',[5],'URL 값을 퍼센트 인코딩했다. 이 변경이 직접 제공하는 것은?',1,[["값의 기밀성을 보장하는 암호화","역변환 가능한 표현 변경은 비밀 보호를 제공하지 않는다."],["바이트를 URL 문맥에 표현하는 방식","퍼센트 인코딩은 표현 규칙이며 암호화나 인가가 아니다."],["서버가 해당 값의 접근 권한을 검증했다는 증거","인코딩과 사용자·객체 인가는 별개다."],["모든 출력 위치에서 스크립트 해석을 막는 보편 방어","URL 표현 규칙 하나가 HTML 등 모든 출력 문맥을 안전하게 만들지 않는다."]],'인코딩을 했더라도 HTTPS·민감 값 최소화·검증이 필요하다.');
q(w11,urls,'fragment-request','concept',[5],'일반 HTTP 요청에서 URL의 조각 식별자 부분에 대한 설명으로 옳은 것은?',3,[["질의 문자열과 마찬가지로 조각 식별자도 항상 서버에 전달된다","질의 부분과 조각 식별자의 처리 경계가 다르다."],["서버가 받지 않으므로 클라이언트 코드에서 사용해도 검증할 필요가 없다","클라이언트가 해석·사용하는 값에는 별도 검증이 필요할 수 있다."],["조각 식별자는 URL에서 암호화된 비밀 저장 영역이다","요청 대상에서 빠진다는 사실이 비밀성과 안전한 저장을 뜻하지 않는다."],["HTTP 요청 대상에 그대로 포함되어 전송되는 부분은 아니다","조각 식별자는 클라이언트 처리 대상이며 일반 요청 대상에 포함되지 않는다."]],'URL 구성요소의 역할과 서버에 전달되는 범위를 구별한다.');

const webarch = objective(w11,'web-boundaries','브라우저·서버·DB의 책임 경계',[6,7,8],
  '브라우저 입력 검사가 있다는 이유만으로 서버가 모든 값을 신뢰하면 사용자가 요청을 직접 바꾸는 경우를 막지 못한다.',
  ['정적 콘텐츠는 미리 준비한 표현을 주고 동적 콘텐츠는 요청 매개변수·쿠키·본문 등을 바탕으로 서버 처리를 거쳐 생성될 수 있다. 웹 서버, 응용 코드, DBMS는 역할이 다르며 DBMS는 자료의 조회·입력·변경·삭제를 관리하는 계층이다. HTML은 구조·표현, JavaScript는 동작을 담당하지만 JavaScript가 브라우저에서만 실행되는 언어라고 제한하지 않는다.',
   '브라우저 검증은 빠른 피드백과 사용성에 유용하지만 클라이언트는 신뢰 경계 밖에 있다. 개발자 도구나 별도 클라이언트가 존재할 수 있으므로 서버가 타입·범위·업무 규칙·권한을 다시 검증해야 한다. 교안의 공격 절차는 대상 발견·약점 확인·지속 접근이라는 위협 흐름을 방어 관점으로 이해한다. 실제 대상 선정·침입·은닉 활동은 하지 않고 가상 사건 기록에서 어느 경계의 검증이 빠졌는지 분석한다.'],
  '클라이언트 검사는 편의, 서버 검증과 자원별 인가는 강제 경계로 사용한다.',
  [['브라우저','사용자 상호작용과 빠른 피드백','필수 항목 누락 안내'],['서버 응용','업무 규칙과 권한의 강제','수량 범위와 주문 권한 확인'],['DBMS','자료의 일관된 저장·질의 처리','승인된 자료 변경과 조회']],
  '가상 주문 화면은 음수 수량을 막지만 서버는 받은 값을 그대로 저장한다.',
  ['브라우저 검사는 우회 가능한 사용성 보조임을 확인한다.','서버가 타입·범위·업무 규칙을 검증한 뒤 저장하도록 책임을 둔다.'],
  '유효성의 최종 강제는 신뢰할 수 있는 서버 경계에 있어야 한다.',
  '화면에서 버튼을 숨기면 해당 작업이 금지된다는 생각은 UI 표시와 서버 인가를 혼동한다.',
  '쿼리 문자열과 쿠키와 POST 본문 중 어느 것이 언제나 신뢰 가능한가?', '어느 것도 출처만으로 신뢰할 수 없다. 클라이언트 제공 값은 모두 서버의 검증과 권한 검사 대상이다.', ['client-validation','html-history']);
q(w11,webarch,'client-only-validation','application',[8],'가상 폼이 JavaScript로 수량을 검사하니 서버 검사를 없애자는 제안은?',1,[["옳다, 브라우저 검사를 통과한 값만 서버에 도착한다","요청을 만드는 경로를 브라우저 폼 하나로 제한할 수 없다."],["틀리다, 서버가 타입·범위·업무 규칙을 다시 검증해야 한다","클라이언트 실행을 우회한 요청도 서버에 도달할 수 있다."],["옳다, 수량이 숫자형이면 최대 구매량 같은 업무 규칙도 자동 충족된다","타입 검사와 허용 범위·업무 제약은 다른 조건이다."],["틀리다, 서버 검증을 위해서는 클라이언트 검사를 모두 제거해야 한다","사용 편의의 클라이언트 검사와 서버의 신뢰 경계 검증은 함께 둘 수 있다."]],'클라이언트 검사는 사용자 경험을 돕지만 신뢰 경계를 만들지 않는다.');
q(w11,webarch,'dbms-role','concept',[7],'웹 응용에서 DBMS의 역할에 가장 가까운 것은?',0,[["자료의 저장·조회·변경을 관리한다","DBMS는 응용이 사용하는 데이터의 관리 기능을 담당한다."],["브라우저의 HTML을 화면에 배치한다","표시 처리와 데이터 관리 계층을 혼동했다."],["클라이언트의 모든 요청을 자동으로 사용자별 인가한다","DBMS 사용만으로 응용의 객체별 권한 검사가 완성되지 않는다."],["HTTP와 TLS의 모든 전송 처리를 대신한다","자료 관리 역할과 웹 전송 계층 역할은 다르다."]],'DBMS를 써도 응용 계층이 입력과 권한을 올바르게 판단해야 한다.');
q(w11,webarch,'untrusted-input-locations','contrast',[7],'서버가 검증해야 할 외부 입력의 조합은?',3,[["주소창 질의 값만 검사하고 본문은 서버 내부 값으로 본다","POST 본문도 클라이언트가 보낼 수 있는 외부 입력이다."],["쿠키는 서버가 처음 만들었으므로 수신 값을 항상 신뢰한다","반환된 쿠키의 유효성·무결성 등도 설계에 맞게 확인해야 한다."],["브라우저 폼에 보이는 필드만 검사하고 숨김 필드는 제외한다","숨김 필드도 클라이언트가 통제할 수 있다."],["질의·쿠키·본문 등 클라이언트 제공 값 모두","전달 위치가 달라도 신뢰 경계를 넘어온 값에는 적절한 검증이 필요하다."]],'같은 업무 값이 어느 경로로 와도 검증 경계가 일관되어야 한다.');
q(w11,webarch,'defensive-lifecycle','application',[6],'교안의 정보 수집→약점 확인→침입→지속 접근 흐름을 방어 학습에 활용하는 적절한 방식은?',2,[["침입 단계가 반드시 이 순서라는 가정으로 예외 기록을 버린다","개념 흐름을 모든 사건의 필수 순서로 일반화하면 안 된다."],["서버 오류가 한 번 있으면 지속 접근까지 성공했다고 기록한다","각 단계의 성공에는 각각의 근거가 필요하다."],["가상 기록에서 노출·검증 누락·비인가 변경 단서를 연결한다","공격 실행 없이도 단계별 방어 경계와 관찰 근거를 학습할 수 있다."],["공개 정보가 있으면 실제 대상에 대한 시험 권한도 얻었다고 본다","정보 공개와 시험 허가는 별개다."]],'과정을 아는 목적은 어느 경계에서 탐지·차단·복구할지 이해하는 것이다.');

const owasp = objective(w11,'owasp-context','OWASP의 판본과 위험 판단',[9,10,11,12,19],
  '서로 다른 판의 순위를 섞어 암기하면 정확한 개념을 알아도 틀린 분류를 정답으로 배우게 된다.',
  ['OWASP Top 10은 웹 응용의 주요 보안 위험을 공유하기 위한 인식 자료이지 모든 조직의 위험을 같은 순위로 확정하는 계산표는 아니다. 위험은 발생 가능성과 영향의 결합으로 살피며 공격자의 능력·기회, 약점 노출과 악용 용이성, 기술적 피해와 금전·평판·개인정보 영향을 함께 고려한다. 숫자 곱셈은 척도가 정해진 모델에서만 해석하고 단순 이름 순위로 업무 우선순위를 결정하지 않는다.',
   '교안의 2017 열은 XSS가 A3, 공격 방어 취약점이 A7, CSRF가 A8, 취약한 API가 A10인 목록으로 공식 2017 최종판과 다르다. 후보안 계열과 일치하는 것으로 보이지만 교안 원전의 정확한 후보판 표기는 확인되지 않아 추정으로 표시한다. 공식 최종판은 민감 데이터 노출·XXE·취약한 접근제어·보안 설정 오류·XSS·안전하지 않은 역직렬화·취약 컴포넌트·불충분한 로깅/모니터링을 포함한다. 교안의 개념은 모두 보존하고 번호를 바르게 한정한다. CSRF·API 통제가 최종판 독립 항목에서 빠졌다고 위험이 사라지는 것은 아니다.'],
  '번호보다 원리와 적용 판본을 먼저 확인하고 실제 자산의 가능성·영향으로 우선순위를 정한다.',
  [['교안의 2017 열','최종판과 다른 역사적 목록','공격 방어 취약점·취약 API 별도 항목'],['공식 2017 최종판','발행된 특정 판의 목록','XXE·역직렬화·로깅 항목 포함'],['실제 위험 평가','조직의 자산·노출·영향 반영','같은 결함도 결제·공개 자료에서 영향이 다름']],
  '가상 팀이 교안의 API 항목 번호를 최신 공식 순위라고 문서에 썼다.',
  ['교안 표와 공식 2017 최종판을 대조하여 번호 불일치를 확인한다.','번호 문제를 제외하고 API 인증·객체 인가·검증·기록이라는 위험 개념은 유지한다.'],
  '판본 혼동을 정정하면서도 실제 통제 개념의 학습을 잃지 않는다.',
  'Top 10에 이름이 없으면 안전하다는 생각은 인식 자료를 모든 위험의 완전 목록으로 오해한 것이다.',
  '패치와 로깅·모니터링은 왜 모두 필요한가?', '패치는 약점을 줄이고 기록·관찰·대응은 남은 시도와 침해를 발견·처리하므로 서로 다른 단계에 작용한다.', ['owasp-version','attack-protection']);
q(w11,owasp,'version-mismatch','evidence',[9,10],'교안 표와 공식 OWASP 2017 최종판의 항목 번호가 다르다. 타당한 처리 방식은?',0,[["판본 차이를 표시하고 개념은 학습하되 잘못된 최종 순위는 정답으로 쓰지 않는다","역사적 분류와 공식 최종판을 구분하여 출처 충돌을 남긴다."],["숫자가 모두 10개이므로 항목과 순서도 같은 것으로 취급한다","같은 항목 수가 내용과 순서의 동일성을 뜻하지 않는다."],["교안 표의 순서를 공식 최종판 순서로 다시 이름 붙인다","다른 판본을 최종판으로 오인하게 만들 수 있다."],["최종판에 독립 항목이 없으면 해당 위험의 방어도 제거한다","분류 변화와 실제 취약점의 존재는 별개다."]],'역사적 교안과 특정 최종판을 구분해야 잘못된 암기를 피할 수 있다.');
q(w11,owasp,'risk-context','application',[9,11],'같은 입력 검증 결함이 공개 안내 조회와 결제 변경에 있다. 조치 우선순위를 정할 때 추가로 볼 것은?',2,[["Top 10의 항목 번호만 비교한다","분류 순위만으로 서비스별 위험을 판단할 수 없다."],["입력 검증 코드의 기술적 결함 여부만 비교한다","같은 기술 결함이라도 도달성과 업무 영향이 달라질 수 있다."],["악용 가능성과 업무·개인정보 영향","같은 결함 유형도 노출·악용 조건과 영향을 함께 보아 우선순위를 정해야 한다."],["해당 기능의 매출 영향만 비교한다","업무 영향은 중요하지만 악용 가능성과 개인정보 등 다른 영향도 함께 보아야 한다."]],'위험은 취약점 명칭만 아니라 해당 자산의 맥락에서 판단한다.');
q(w11,owasp,'missing-list-not-safe','contrast',[9,10,12],'CSRF가 특정 최종판의 독립 항목에 없다는 이유로 방어를 제거하자는 주장은?',1,[["옳다, 독립 항목에서 빠지면 브라우저의 자동 인증 전송도 중단된다","분류 목록의 변경은 브라우저 동작을 바꾸지 않는다."],["틀리다, 목록 구조 변경이 공격 원인의 소멸을 뜻하지 않는다","위험 목록은 완전한 방어 체크리스트나 취약점의 소멸 증명이 아니다."],["옳다, 최신 순위에 없는 위험은 해당 서비스에서 평가하지 않는다","실제 기능과 공격 조건을 평가해야 한다."],["틀리다, CSRF는 모든 판본에서 항상 같은 번호로 독립 등재된다","방어 필요성과 판본별 분류는 구분하며 고정 번호 주장은 사실이 아니다."]],'분류에 이름이 남았는지보다 실제 실패 조건과 방어 필요성을 본다.');
q(w11,owasp,'patch-monitor-response','application',[19],'가상 서비스가 패치는 했지만 의심 요청을 기록·경보·조사하지 않는다. 남는 과제는?',3,[["패치가 완료되면 과거 의심 요청의 조사도 모두 불필요하다","패치는 과거 영향 여부를 자동으로 밝히지 않는다."],["사고 연결을 쉽게 하려고 비밀번호와 원문 세션 토큰을 전부 기록한다","기록 자체가 비밀 유출 경로가 되지 않도록 제한해야 한다."],["모든 보안 이벤트를 동일한 긴급도로 알리면 조사 설계는 필요 없다","위험 기반 경보와 조사·대응 연결 없이 경보 수만 늘려서는 충분하지 않다."],["민감 값을 제외한 보안 기록과 경보·대응 연결을 마련한다","예방 패치와 이상 행위의 탐지·조사 능력을 함께 갖춰야 한다."]],'공격 방어 개념은 단일 패치보다 입력 검증·관찰·대응의 연결을 포함한다.');

const injection = objective(w11,'injection','데이터가 질의·명령으로 바뀌는 경계',[11,13],
  '서버가 처리한 입력이라는 이유로 안전한 것은 아니다. 외부 값이 해석 규칙이 되는 순간을 찾아야 한다.',
  ['인젝션은 신뢰하지 않는 데이터가 SQL·OS·LDAP 같은 해석기의 질의·명령 구조에 영향을 주는 실패다. 서버 언어가 특정 이름인지보다 외부 값과 해석 규칙을 어떻게 결합하는지가 원인이다. 정상 검색 값은 조건의 데이터여야 하지만 문자열 결합이 이를 질의 구조로 받아들이게 하면 의도한 접근 범위를 벗어날 수 있다.',
   'SQL에서는 매개변수화된 질의로 구조와 값을 분리하고, 타입·범위 허용 검증과 DB 최소 권한을 함께 둔다. 매개변수화가 모든 동적 식별자나 OS 명령 문제를 자동 해결하는 것은 아니므로 각 API의 안전한 사용 조건을 확인한다. XXE는 XML 파서의 외부 엔티티 처리 문제라는 별도 원리가 있어 교안의 인젝션 예 나열만으로 SQL과 동일한 조치라 보지 않는다. 학습은 가상 자료 흐름으로 하며 작동하는 주입 문자열은 제공하지 않는다.'],
  '입력은 구조가 아닌 값으로 전달하고 해석기·권한에 맞는 통제를 선택한다.',
  [['문자열 결합','외부 값이 구조에 섞일 위험','검색 문장을 입력으로 이어 붙임'],['매개변수화','구조와 값의 역할을 분리','검색 값은 지정된 인자로 전달'],['최소 DB 권한','실패 시 영향 범위 제한','조회 기능에는 필요한 조회만 허용']],
  '가상 검색기가 외부 검색어를 질의 문장에 직접 결합한다.',
  ['검색어가 데이터 자리만 차지하는지 질의 구조도 바꿀 수 있는지 확인한다.','매개변수화와 허용 타입 검증을 적용하고 DB 계정의 필요 권한만 남긴다.'],
  '해석 경계를 지키고 실패 시 권한 영향도 줄인다.',
  '특수문자를 몇 개 지우면 모든 인젝션이 사라진다는 생각은 해석기 문맥과 데이터·구조 분리를 빠뜨린다.',
  'DB가 암호화되어 있으면 인젝션으로 읽기 문제도 자동 해결되는가?', '아니다. 응용 계정이 정당한 경로에서 복호화·조회할 수 있다면 권한 없는 요청도 그 경로를 악용할 수 있어 질의와 인가를 보호해야 한다.', ['xxe-context']);
q(w11,injection,'interpreter-boundary','concept',[11,13],'인젝션을 가장 잘 설명한 것은?',1,[["외부 값이 고정 질의의 매개변수 데이터로만 전달된다","의도된 구조·값 분리는 주입 원인과 반대 방향이다."],["외부 값이 해석기의 질의·명령 구조에 영향을 준다","데이터로 다뤄야 할 값이 실행 의미를 바꾸는 경계 혼동이다."],["사용자가 보낸 모든 잘못된 값이 저장 공간을 초과한다","주입과 버퍼 경계 초과는 같은 원인이 아니다."],["인증된 사용자가 권한 있는 자료를 정상 조회한다","외부 입력 사용 자체가 아니라 해석 구조에 미치는 영향이 핵심이다."]],'문제는 외부 자료가 어느 권한으로 어떤 규칙에 의해 해석되는지다.');
q(w11,injection,'parameterized-query','application',[13],'가상 검색 기능에서 SQL 구조와 검색 값을 분리하는 기본 통제는?',0,[["매개변수화된 질의 사용","질의 구조와 검색 값을 구분하여 값이 SQL 구문으로 해석되지 않게 한다."],["검색 값을 URL 인코딩한 뒤 SQL 문자열에 직접 이어 붙인다","전송 표현 변경이 SQL 해석 경계를 분리하지 않는다."],["클라이언트에서 따옴표만 지우고 서버에서 문자열을 조립한다","클라이언트 삭제 규칙은 우회될 수 있고 구조 분리도 보장하지 않는다."],["응용 DB 계정에 관리 권한을 추가하여 오류를 줄인다","권한 확대는 질의 구조 혼동을 고치지 않으며 영향을 키울 수 있다."]],'서버 입력 검증과 DB 권한 제한도 함께 적용한다.');
q(w11,injection,'least-db-privilege','application',[13],'조회 전용 기능의 DB 계정에 관리 권한까지 주지 않는 이유는?',3,[["권한을 줄이면 모든 SQL 구문 오류가 자동 수정되기 때문에","권한 제한은 질의 작성의 오류를 고치는 기능이 아니다."],["조회 계정은 어떤 자료에 접근해도 기밀성 피해가 없기 때문에","읽기만 가능해도 민감 자료 유출이 생길 수 있다."],["관리 권한이 없으면 서버 입력 검증이 필요 없기 때문에","최소 권한은 구조 분리와 입력 검증을 대신하지 않는다."],["결함이 악용되어도 수행 가능한 작업 범위를 줄이기 위해서","최소 권한은 근본 결함 수정과 함께 피해 범위를 제한한다."]],'예방 통제가 실패했을 때의 피해 범위를 줄이는 보완 층이다.');
q(w11,injection,'xxe-different-control','contrast',[13],'XXE를 SQL 인젝션과 같은 이름 아래 묶었다는 이유로 SQL 매개변수화만 적용했다. 남는 문제는?',2,[["SQL 값을 매개변수화했으면 XML 파서도 같은 규칙으로 보호된다","SQL 통제가 XML의 외부 자원 해석을 자동 변경하지 않는다."],["XML 파일 확장자를 바꾸면 외부 엔티티 처리가 중단된다","이름 변경은 실제 파서의 설정과 동작을 고치지 않는다."],["XML 외부 엔티티 처리 설정 등 별도 파서 경계를 검토해야 한다","SQL 질의와 XML 파서는 서로 다른 해석 경계다."],["DB 계정을 읽기 전용으로 하면 XML 파서의 모든 외부 접근도 차단된다","DB 권한과 XML 파서의 외부 자원 접근은 별개다."]],'분류의 넓은 유사성보다 실제 해석기의 위험 동작을 기준으로 대응한다.');

const session = objective(w11,'session','세션 토큰은 로그인 뒤의 인증 자료',[11,14],
  '비밀번호를 안전하게 만들었어도 로그인 뒤 토큰이 유출되거나 계속 살아 있으면 다른 사람이 세션을 사용할 수 있다.',
  ['인증은 신원을 확인하는 과정이고 세션은 여러 요청을 그 인증 상태와 연결하는 장치다. 세션 토큰이 사실상 접근 자격증명 역할을 하면 복사된 토큰만으로 다른 사람의 상태를 이용할 수 있다. URL에 토큰을 넣으면 방문 기록·공유·중간 기록 등 노출 경로가 늘 수 있으므로 단순히 이름이 어렵다는 이유로 안전하다고 보지 않는다.',
   '보호는 토큰의 예측 어려움뿐 아니라 HTTPS, 쿠키의 적절한 보호 속성, 로그인·권한 변화 시 갱신, 종료·만료·서버 무효화까지 포함한다. HttpOnly는 JavaScript의 쿠키 읽기를 제한하는 보충 수단이지만 XSS가 할 수 있는 모든 동작을 없애지는 않는다. 로그에는 토큰 값을 직접 남기지 않고 사건 연결에 필요한 최소 정보만 안전하게 기록한다.'],
  '세션도 발급·전달·갱신·만료·폐기를 갖는 인증 자료로 관리한다.',
  [['비밀번호','처음 인증 등에 쓰는 비밀','사용자 로그인 증명'],['세션 토큰','여러 요청을 인증 상태에 연결','로그인 후 요청의 상태 연결'],['로그아웃','현재 상태를 끝내는 수명 주기 동작','서버에서 토큰 사용 불가 처리']],
  '가상 포털이 로그아웃 화면만 표시하고 서버에서는 기존 토큰을 계속 수락한다.',
  ['화면 전환과 실제 토큰 무효화가 다른 동작임을 확인한다.','이후 요청에서 서버가 종료된 세션을 거절하도록 수명 주기를 설계한다.'],
  '인증 상태 종료는 화면 문구만으로 완료되지 않는다.',
  '토큰은 암호처럼 보이니 로그에 적어도 된다는 생각은 토큰 자체가 권한 행사를 가능하게 한다는 점을 놓친다.',
  '비밀번호가 강해도 세션 관리 결함이 위험한 이유는?', '공격자가 비밀번호를 맞히지 않고도 살아 있는 토큰이나 잘못된 상태 연결을 이용할 수 있기 때문이다.');
q(w11,session,'url-token-exposure','application',[14],'가상 서비스가 세션 토큰을 URL에 넣는다. 주요 추가 노출 경로는?',0,[["방문 기록·공유된 링크·요청 기록","URL에 있는 토큰은 URL을 저장·공유하는 경로로 추가 노출될 수 있다."],["서버가 토큰을 무효화한 뒤에도 언제나 인증이 성공하는 경로","노출 경로와 서버가 무효 토큰을 거부하는지는 별개의 문제다."],["비밀번호 추측 횟수 제한이 자동 해제되는 경로","토큰을 URL에 둔다는 사실만으로 로그인 제한이 해제되지 않는다."],["댓글의 HTML 출력 정화가 자동 중단되는 경로","URL 토큰 전달과 댓글 출력 처리는 별도의 경계다."]],'토큰의 전달 위치와 기록 정책도 자격증명 보호의 일부다.');
q(w11,session,'logout-invalidation','application',[14],'로그아웃 화면 후 기존 토큰을 서버가 계속 수락한다. 고쳐야 할 경계는?',2,[["브라우저 쿠키만 삭제하고 서버는 기존 토큰을 계속 수락한다","이미 복사된 토큰까지 거부하려면 로컬 삭제만으로 충분하지 않다."],["로그아웃 후 탭만 닫고 토큰 유효성 처리는 그대로 둔다","탭 닫기는 서버의 유효성 판단을 바꾸지 않는다."],["서버의 세션 종료·무효화 처리","화면이 바뀌어도 서버가 기존 토큰을 수락하면 인증 상태가 남아 있다."],["로그아웃 안내 화면으로 이동하되 서버 세션은 유지한다","화면 전환 자체는 서버 인증 상태를 종료하지 않는다."]],'사용자에게 보이는 종료와 서버가 강제하는 종료를 일치시켜야 한다.');
q(w11,session,'password-not-session','contrast',[14],'강한 비밀번호만으로 세션 탈취 위험이 사라지지 않는 이유는?',1,[["강한 비밀번호로 로그인하면 세션 토큰이 외부에 공개되어도 안전해서","유효 토큰을 가진 주체의 악용 가능성을 별도로 통제해야 한다."],["로그인 뒤 접근 자료인 토큰의 전달·유효 기간·무효화도 보호해야 해서","비밀번호 인증 이후에도 토큰을 통한 접근 경계가 남는다."],["세션 토큰이 있으면 비밀번호 강도는 모든 상황에서 무관해서","초기 인증과 이후 토큰 보호는 함께 필요하다."],["비밀번호 길이를 늘리면 기존 토큰이 항상 즉시 폐기돼서","비밀번호 길이만으로 세션 유효성이 자동 변경되지 않는다."]],'인증과 인증 후 상태 유지는 연결되지만 같은 통제 하나로 끝나지 않는다.');
q(w11,session,'safe-logging','application',[14,19],'가상 보안 로그에 세션 사고를 남길 때 적절한 설계는?',3,[["사고 재현을 위해 원문 세션 토큰과 비밀번호를 저장한다","기록을 통한 재사용 가능한 비밀 유출 위험이 생긴다."],["개인정보 위험을 피하려면 성공·실패·시각을 포함한 모든 사건 기록을 없앤다","필요한 최소 기록을 설계하는 것과 모든 조사 근거 삭제는 다르다."],["보안 로그라면 누구나 열람할 수 있게 영구 보존한다","접근 제한과 보존 범위도 함께 설계해야 한다."],["민감 값 없이 필요한 사건 연결 정보를 제한적으로 기록한다","조사 가능성을 확보하면서 기록 자체의 비밀 노출을 줄인다."]],'진단 편의성을 이유로 인증 자료를 수집·공개하지 않는다.');

const xss = objective(w11,'xss','브라우저에서 데이터가 코드가 되는 실패',[11,15],
  '서버가 저장한 글이라도 브라우저가 코드로 해석하면 다른 이용자의 권한으로 동작할 수 있다.',
  ['XSS는 신뢰하지 않는 값이 브라우저의 HTML·JavaScript 같은 실행 가능한 문맥에 안전하지 않게 들어가 발생한다. 저장된 게시물, 응답에 반영된 값, 클라이언트가 DOM에 넣는 값 등 전달 경로는 달라도 원리는 외부 데이터를 코드처럼 해석하는 경계 실패다. 서버에서 한 번 처리한 값이라고 신뢰가 자동 생기지 않는다.',
   '일반 글을 표시할 때는 텍스트로 넣고, HTML·속성·URL 등 문맥마다 알맞은 검증·출력 인코딩을 적용한다. 의도적으로 풍부한 HTML을 허용할 때는 적합한 정화가 필요하다. 서버 입력 검증 하나나 공통 특수문자 삭제 하나로 모든 출력 문맥을 보호하지 못한다. CSP와 HttpOnly 같은 보충 통제는 피해를 줄일 수 있으나 안전하지 않은 출력 경계를 직접 고치는 일을 대체하지 않는다.'],
  '화면에 넣는 위치의 해석 규칙을 보고 외부 값을 코드가 아닌 데이터로 처리한다.',
  [['텍스트 표시','입력을 문자로 보이게 함','게시글의 꺾쇠도 글자로 표시'],['HTML 해석','입력을 구조·동작으로 해석할 수 있음','신뢰 안 된 값을 마크업에 직접 삽입'],['문맥별 인코딩','넣는 위치에 맞게 의미를 제한','HTML 본문과 URL 속성을 구분']],
  '가상 게시판이 사용자 글을 HTML로 직접 해석하여 표시한다.',
  ['사용자 글이 단순 텍스트인지 의도적으로 허용한 HTML인지 요구를 구분한다.','일반 글이면 안전한 텍스트 표시를 사용하고 허용 HTML이면 검증된 정화와 문맥별 통제를 설계한다.'],
  '표시 요구를 만족하면서도 사용자가 브라우저 코드 구조를 통제하지 못하게 한다.',
  'HTTPS면 XSS가 사라진다는 생각은 전송 보호와 브라우저 해석 경계를 혼동한다.',
  '입력 때 한 번 검사했어도 출력 문맥을 다시 살펴야 하는 이유는?', '같은 값도 HTML 본문·속성·스크립트·URL에서 다르게 해석되어 필요한 보호가 달라지기 때문이다.', ['xss-controls']);
q(w11,xss,'xss-execution-boundary','concept',[15],'XSS에서 주된 코드 해석이 일어나는 위치는?',2,[["DBMS의 SQL 질의 해석 문맥","SQL 인젝션의 해석 경계와 구분한다."],["서버 운영체제의 명령 셸 문맥","운영체제 명령 주입의 직접 해석 위치와 구분한다."],["피해 이용자의 브라우저 문맥","신뢰되지 않은 값이 페이지의 코드로 해석되는 경계가 핵심이다."],["XML 파서의 외부 엔티티 해석 문맥","XXE의 해석 경계와 XSS는 다르다."]],'SQL 인젝션의 서버 질의 해석과 XSS의 브라우저 출력 해석을 구별한다.');
q(w11,xss,'safe-text-output','application',[15],'가상 댓글은 HTML 서식을 허용하지 않는다. 가장 직접적인 출력 설계는?',0,[["사용자 글을 텍스트로 표시한다","서식을 허용하지 않는 기능에서는 사용자 문구를 마크업으로 해석할 필요가 없다."],["HTML로 해석하되 특정 스크립트 단어만 삭제한다","단어 삭제만으로 마크업과 실행 가능 문맥을 안전하게 처리하지 못한다."],["URL 인코딩만 한 뒤 HTML 코드로 직접 삽입한다","URL 표현 변경은 HTML 출력 문맥에 맞는 보호를 대신하지 않는다."],["HttpOnly 쿠키를 켜고 댓글 HTML 해석은 그대로 둔다","쿠키 읽기 제한은 댓글 값의 코드 해석 원인을 없애지 않는다."]],'요구가 일반 텍스트라면 실행 가능한 문맥에 입력을 넣지 않는 것이 핵심이다.');
q(w11,xss,'context-specific-encoding','contrast',[15],'모든 출력 위치에 같은 문자 삭제 규칙 하나만 적용하는 접근의 한계는?',3,[["입력에 영문자가 없으면 모든 문맥에서 안전해서","문자 종류 하나만으로 모든 해석 경계의 안전성을 판단할 수 없다."],["HTTPS가 출력 문자열을 자동으로 정화해서","전송 암호화와 브라우저 코드 해석은 다른 경계다."],["서버가 만든 페이지면 외부 입력도 자동으로 신뢰되어서","페이지 생성 주체와 포함된 값의 신뢰 여부는 별개다."],["HTML 본문·속성·URL 등 문맥의 해석 규칙이 달라서","출력 위치별 의미에 맞는 처리와 위험한 삽입 위치 회피가 필요하다."]],'출력할 위치를 모르는 일괄 처리만으로 모든 해석 경계를 보장하기 어렵다.');
q(w11,xss,'httponly-limit','application',[14,15],'가상 팀이 HttpOnly를 켰으니 XSS를 고칠 필요가 없다고 한다. 정확한 평가는?',1,[["옳다, HttpOnly는 모든 사용자 입력을 텍스트로 바꾼다","쿠키 속성은 페이지의 출력 해석 방식을 바꾸지 않는다."],["틀리다, 쿠키 읽기를 제한해도 브라우저 내 다른 악용 가능성은 남는다","HttpOnly는 특정 쿠키 접근 통제이며 XSS 발생 원인을 수정하지 않는다."],["옳다, 쿠키를 읽지 못하면 브라우저에서 인증 요청도 보낼 수 없다","쿠키 읽기 제한과 브라우저의 요청 전송 가능성은 다르다."],["틀리다, HttpOnly 쿠키는 보안 효과가 전혀 없으니 제거해야 한다","불완전한 방어라는 사실이 쿠키 읽기 제한의 가치를 없애지는 않는다."]],'피해 완화 장치를 썼다고 외부 값의 코드 해석 문제를 남겨 두지 않는다.');

const access = objective(w11,'access','로그인 이후의 객체·기능 권한',[11,16],
  '자신의 계정으로 로그인한 사람이 다른 사람의 자료를 읽을 수 있다면 인증이 정상이어도 접근 제어는 실패한 것이다.',
  ['접근 제어는 누가 어떤 자원에 어떤 동작을 할 수 있는지 제한한다. 인증은 사용자를 식별하지만 그 사용자에게 모든 객체·기능을 허용하지 않는다. 교안의 다른 계정 식별자로 자료를 조회하는 사례는 객체 소유권·관계 검사 누락을 보여 준다. 일반 사용자가 관리자 기능을 호출하는 문제는 기능 수준 권한 검사 누락이다.',
   '서버는 요청마다 사용자·대상 객체·작업·관계를 평가하고 기본 거부와 최소 권한을 적용한다. 화면에서 링크를 숨기거나 식별자를 길고 추측하기 어렵게 만드는 것은 서버의 인가를 대체하지 못한다. 객체 식별자는 클라이언트가 제공할 수 있으므로 신뢰하지 않고, 읽기와 수정·삭제도 별도 권한으로 다룬다. API에서도 같은 원리가 적용된다.'],
  '요청마다 주체·대상·동작의 관계를 서버에서 확인한다.',
  [['객체 수준','해당 자료에 접근할 관계가 있는지','자기 주문만 조회'],['기능 수준','그 작업을 수행할 역할이 있는지','관리자만 권한 설정 변경'],['UI 표시','사용성에 필요한 버튼·링크 노출','관리 메뉴를 화면에서 숨김']],
  '가상 포털에서 로그인한 사용자가 다른 학생의 성적 번호로 조회를 요청했다.',
  ['로그인 성공과 해당 성적을 볼 권한을 분리한다.','서버가 소유·담당 관계를 확인하고 허가되지 않은 객체 접근을 거절한다.'],
  '식별자가 유효해도 사용자에게 조회 권한이 있다는 뜻은 아니다.',
  '식별자가 복잡하니 권한 검사가 필요 없다는 생각은 추측 어려움과 허용 여부를 혼동한다.',
  '조회가 허용된 사용자에게 수정도 자동 허용해도 되는가?', '안 된다. 읽기·쓰기·삭제는 영향이 달라 각각의 작업 권한을 확인해야 한다.');
q(w11,access,'authenticated-other-record','application',[16],'가상 사용자 A가 로그인 후 B의 비공개 주문을 조회할 수 있다. 주된 결함은?',1,[["오직 비밀번호 길이 부족","A의 정상 로그인 후 타인 객체 조회라는 상황은 객체 인가 경계를 가리킨다."],["객체 수준 접근 제어 누락","로그인 여부 외에 요청한 주문과 사용자의 권한 관계를 검사해야 한다."],["응답을 JSON으로 보내는 형식 오류","표현 형식을 바꾸어도 객체 권한 누락이 고쳐지지 않는다."],["서버가 검색 값을 SQL 매개변수로 전달한 것","구조와 값 분리는 필요한 통제이며 타인 주문 인가를 대신하지는 않는다."]],'인증 성공이 모든 객체 접근 허가를 의미하지 않는다.');
q(w11,access,'hidden-admin-button','application',[16],'관리 버튼을 화면에서 숨겼지만 서버의 관리 요청은 일반 사용자도 처리한다. 필요한 수정은?',3,[["관리 버튼을 더 깊은 메뉴로 옮긴다","발견을 어렵게 해도 서버 처리 권한은 그대로다."],["클라이언트가 보내는 관리자 여부 필드만 신뢰한다","요청자가 통제하는 값만으로 관리 권한을 결정하면 안 된다."],["관리 URL을 긴 무작위 이름으로 바꾸고 권한 검사는 생략한다","경로 비공개는 요청 주체의 권한 검증을 대신하지 않는다."],["서버가 요청마다 관리 작업 권한을 검사한다","화면 표시와 독립적으로 실제 처리 지점에서 인가해야 한다."]],'UI 상태와 독립적으로 서버가 기능 수준 인가를 강제해야 한다.');
q(w11,access,'unguessable-id-limit','contrast',[16],'자료 식별자를 추측하기 어렵게 만들었다. 그래도 필요한 것은?',0,[["사용자와 해당 자료의 접근 관계 검사","추측 어려운 ID도 유출·공유될 수 있으므로 인가 검사가 필요하다."],["ID 길이만 늘리고 로그인 사용자면 모두 허용","사용자 인증과 객체별 권한은 다르다."],["ID가 비밀이라는 이유로 접근 기록과 권한 검사를 제거","식별자 난수성은 인가와 감사의 대체물이 아니다."],["ID를 URL 인코딩한 요청은 소유자 요청으로 간주","인코딩은 요청자의 권한을 입증하지 않는다."]],'링크가 유출되거나 식별자를 알게 된 경우도 서버가 허가 여부를 판단해야 한다.');
q(w11,access,'read-write-permissions','concept',[16],'문서 조회 권한이 있는 사용자의 수정 요청을 다룰 때 올바른 원칙은?',2,[["조회가 허용되면 수정·삭제도 모두 허용한다","읽기 권한이 모든 변경 권한을 포함하지 않는다."],["수정 요청이 POST이면 권한 검사를 생략한다","메소드 자체는 사용자의 작업 권한을 입증하지 않는다."],["수정 권한을 별도로 검사한다","조회와 수정은 서로 다른 작업이며 허용 범위가 다를 수 있다."],["문서 ID가 같으면 요청한 작업의 종류는 검사하지 않는다","같은 객체에도 작업별 권한 차이가 있다."]],'작업 종류가 달라지면 같은 사용자·객체라도 다른 인가 판단이 필요하다.');

const config = objective(w11,'configuration-data','설정·암호화·로그의 서로 다른 보호',[12,16,17,18,19],
  'TLS나 저장 암호화 한 가지만 켰다고 기본 계정·공개 파일·불필요한 로그 노출까지 해결되는 것은 아니다.',
  ['보안 설정 오류에는 기본 계정, 사용하지 않는 페이지·서비스, 공개되면 안 되는 파일, 과도한 오류 정보, 갱신되지 않은 구성 등이 포함된다. 웹 서버만이 아니라 프레임워크·응용·DB·플랫폼의 실제 배포 설정까지 유지해야 한다. 외부 응답에는 필요한 오류 안내만 주고 내부 진단은 접근 제한된 기록에 남긴다. 기본값을 한 번 바꾸는 것으로 끝나지 않고 변경·배포 후에도 검증한다.',
   '민감 자료는 필요한 수집량·저장 기간을 줄이고 전송·저장 암호화, 키 분리·접근 통제, 최소 권한을 결합한다. DB가 암호화되어도 응용이 자동 복호화해서 읽는 경로를 인젝션이나 인가 결함으로 악용하면 자료가 노출될 수 있다. 로그·모니터링은 사건을 알아차리고 대응할 때 필요하지만 비밀번호·세션 토큰·불필요한 개인정보를 기록하면 또 다른 저장소 노출을 만든다.'],
  '배포 설정, 자료 접근, 암호키, 진단 기록을 각각 보호하고 실제 요청 결과로 확인한다.',
  [['전송 암호화','통신 중 내용 보호','HTTPS 사용'],['저장 암호화','저장 매체의 자료 보호','접근 제한된 키로 저장 자료 보호'],['응용 인가','정당한 요청만 자료를 사용','사용자별 비공개 자료 조회 제한']],
  '가상 DB는 암호화되었지만 응용 계정은 모든 고객 자료를 복호화하여 반환할 수 있다.',
  ['저장 매체 보호와 응용을 통한 정당·부당 조회를 구분한다.','응용 인가·질의 안전성·DB 최소 권한과 반환 자료 범위를 점검한다.'],
  '저장 암호화만으로 응용 경로를 통한 노출은 해결되지 않는다.',
  '오류 내용을 전부 사용자에게 보여 주면 보안도 좋아진다는 생각은 진단 편의와 정보 노출의 차이를 놓친다.',
  '사용자 오류 안내와 내부 진단 기록을 나누는 이유는?', '이용자에게 필요한 안내는 제공하면서 내부 구조·비밀의 노출은 줄이고, 접근 제한된 자료로 조사 가능성을 확보하기 위해서다.', ['storage-encryption']);
q(w11,config,'verbose-errors','application',[16,17],'가상 공개 오류 화면에 DB 경로와 내부 구성 정보가 길게 표시된다. 적절한 개선은?',2,[["외부에도 전체 진단을 보여 주되 응답 코드를 200으로 바꾼다","상태 코드 변경은 응답 본문의 민감한 정보를 숨기지 않는다."],["진단 정보 유출을 막기 위해 내부 오류 기록도 모두 삭제한다","접근 통제된 조사 근거까지 없앨 필요는 없다."],["외부에는 제한된 안내, 내부에는 비밀을 제외한 접근 제한 진단을 둔다","사용자 안내와 운영 조사 정보를 분리하여 불필요한 내부 노출을 줄인다."],["오류 경로만 URL 인코딩하면 외부에 전부 공개해도 된다","표현 변경은 정보 공개 범위를 줄이지 않는다."]],'정보 최소화와 조사 가능성을 함께 만족해야 한다.');
q(w11,config,'encrypted-db-application-path','application',[18],'저장 암호화된 가상 DB를 응용이 자동 복호화하여 읽는다. 인가 결함이 남으면?',0,[["응용의 조회 경로를 통해 비인가 노출이 가능하다","응용이 복호화할 수 있다면 그 접근 경로의 인가가 여전히 필요하다."],["저장 암호화가 모든 응용 객체 권한 검사를 대신한다","저장 매체 보호와 응용의 접근 권한은 다른 경계다."],["인증에 성공한 사용자는 암호화된 모든 자료를 조회해도 된다","로그인과 자료별 인가를 혼동했다."],["암호화 키가 비밀이면 응용의 비인가 응답은 기밀성 피해가 아니다","응용이 평문을 반환하면 키를 직접 얻지 않아도 노출이 가능하다."]],'암호화는 접근통제와 질의 안전성을 대체하지 않는다.');
q(w11,config,'configuration-layers','concept',[12,16],'보안 구성 관리 범위에 대한 올바른 설명은?',3,[["개발 PC 설정만 안전하면 운영 배포도 같은 것으로 간주한다","실제 배포의 설정과 구성요소를 확인해야 한다."],["최초 설치 직후 점검했으면 이후 변경은 검토하지 않는다","운영 변경과 구성 변화에 따라 지속 점검이 필요하다."],["응용 코드 검사만으로 웹 서버와 DB의 기본 설정도 검증된다","각 배포 층의 설정 경계를 따로 확인해야 한다."],["플랫폼·서버·응용·DB 등 실제 배포 층을 지속 점검한다","구성 위험은 단일 코드 층에만 한정되지 않는다."]],'운영 구성은 코드와 함께 바뀌므로 배포 뒤 실제 접근 결과도 확인한다.');
q(w11,config,'data-minimization','application',[18],'가상 서비스가 쓰지 않는 민감 항목을 오래 저장한다. 암호화 외에 직접 줄일 수 있는 위험은?',1,[["암호화 키만 주기적으로 바꾸고 불필요한 자료는 무기한 늘린다","암호화 관리가 불필요한 수집·보존의 위험을 없애지 않는다."],["필요 없는 수집을 중단하고 보존 범위를 줄인다","자료 최소화는 보관 중 유출될 자료의 양과 기간을 줄인다."],["접근 권한을 가진 계정을 늘려 자료 관리 책임을 분산한다","불필요한 접근 확대는 자료 최소화와 반대 방향이다."],["보관 자료의 이름만 바꾸면 더는 민감 자료가 아니다","식별 가능한 내용이 남으면 이름 변경만으로 위험이 사라지지 않는다."]],'필요한 자료만 보유하는 것은 암호화와 별개의 보호 층이다.');

const csrf = objective(w11,'csrf','쿠키의 자동 첨부와 사용자의 의도',[12,20],
  '서버가 유효한 쿠키를 받았다는 사실만으로 사용자가 그 변경을 직접 원했다고 믿으면 요청 위조를 놓칠 수 있다.',
  ['CSRF는 브라우저가 자동 첨부하는 인증 정보를 이용하여, 로그인한 사용자가 의도하지 않은 상태 변경 요청을 보내도록 유도하는 문제다. 핵심은 쿠키의 유효성만으로 요청의 의도·출처를 확인하지 못하는 데 있다. 공격자가 서버 비밀번호를 알아야만 가능한 것은 아니며 XSS와도 다른 원리다.',
   '상태 변경은 GET 조회와 분리하고 서버에서 CSRF 토큰·출처 검증 등 요청 특성에 맞는 통제를 적용한다. SameSite 쿠키는 교차 사이트 자동 첨부를 줄이는 보충 통제이며 모든 구성의 완전 대체로 보지 않는다. POST로 바꿨다는 사실이나 HTTPS만으로 CSRF가 사라지지 않는다. API도 인증 정보가 어떤 방식으로 전달되는지에 따라 평가하며 명칭만으로 안전을 판단하지 않는다.'],
  '유효한 인증 자료와 정당한 변경 의도는 별도로 검증한다.',
  [['인증 쿠키','브라우저가 조건에 따라 자동 첨부','로그인 상태를 요청과 연결'],['CSRF 방어 토큰','요청 정당성을 검증하는 추가 값','상태 변경 시 서버 검증'],['XSS와 CSRF','코드 해석과 요청 의도 검증의 차이','브라우저 코드 실행과 자동 인증 정보 악용']],
  '가상 사이트는 쿠키가 있으면 잔액 변경 요청을 수락하며 CSRF 검증이 없다.',
  ['쿠키가 유효하다는 사실과 사용자가 의도한 요청이라는 사실을 분리한다.','상태 변경에 토큰·출처 검증을 설계하고 쿠키 속성·권한 검사도 함께 적용한다.'],
  '로그인 상태 확인만으로 변경 요청을 신뢰하지 않는다.',
  'POST는 주소창에 안 보이니 CSRF도 막는다는 생각은 전송 위치와 자동 인증 정보의 관계를 혼동한다.',
  'XSS가 없어도 CSRF가 가능한 이유는?', '서버가 자동 첨부된 인증 정보만 신뢰하고 요청의 정당성을 확인하지 않는 별도 경계 실패이기 때문이다.');
q(w11,csrf,'csrf-intent','concept',[20],'CSRF가 악용하는 핵심 신뢰 오류는?',1,[["사용자 문구가 HTML 코드로 해석됨","이는 주로 XSS의 해석 경계를 설명한다."],["자동 첨부된 인증 정보만으로 변경 의도를 신뢰함","인증 정보의 존재와 이용자가 해당 요청을 의도했다는 사실은 다르다."],["검색 값이 SQL 질의 구조를 바꿈","이는 SQL 인젝션의 핵심 원인과 관련된다."],["외부 입력이 서버 버퍼 경계를 넘어 기록됨","이는 메모리 경계 오류의 설명이며 CSRF 신뢰 오류와 다르다."]],'세션 소유 확인만으로 사용자의 구체적인 변경 의도를 증명할 수 없다.');
q(w11,csrf,'post-not-csrf-control','application',[20],'가상 서비스가 변경 요청을 POST로 옮겼으니 CSRF 토큰이 필요 없다고 한다. 정확한 평가는?',0,[["POST만으로 자동 인증 정보 악용이 사라지지 않아 별도 검증이 필요하다","메소드 선택과 요청 의도의 검증은 서로 다른 경계다."],["POST 본문은 다른 사이트에서 어떤 방식으로도 전송할 수 없다","브라우저가 교차 사이트 POST를 전혀 만들지 못한다는 전제가 잘못됐다."],["POST이면 서버가 이용자의 변경 의도를 자동 확인한다","메소드는 사용자 의도의 증명이 아니다."],["HTTPS만 추가하면 토큰·출처 검증은 항상 불필요하다","전송 보호만으로 의도하지 않은 인증 요청을 배제할 수 없다."]],'상태 변경의 메소드 선택과 CSRF 방어는 함께 적용할 문제다.');
q(w11,csrf,'xss-csrf-distinction','contrast',[15,20],'XSS와 CSRF를 구분한 설명으로 옳은 것은?',3,[["둘 다 SQL 해석 구조 변경이므로 매개변수 질의 하나로 해결한다","브라우저 코드 해석과 요청 정당성은 SQL 경계와 별개다."],["CSRF가 있으면 피해 브라우저에서 반드시 주입 스크립트가 실행된다","주입 코드 실행은 CSRF의 필수 조건이 아니다."],["XSS가 없으면 CSRF도 성립할 수 없다","서로 구별되는 원인이며 XSS 부재가 요청 정당성을 보증하지 않는다."],["XSS는 브라우저 코드 해석, CSRF는 의도하지 않은 인증 요청의 문제다","두 원인과 직접 통제는 다르며 결합될 수도 있다."]],'결합될 수 있어도 원리와 기본 방어를 구별해야 한다.');
q(w11,csrf,'samesite-supplement','application',[20],'SameSite 쿠키를 적용한 가상 서비스에서 남은 점검은?',2,[["SameSite라는 속성이 있으면 값과 동작 조건은 확인하지 않는다","설정 값과 실제 요청 상황에 따라 동작이 달라질 수 있다."],["같은 사이트에서 오는 요청은 사용자 의도를 검사하지 않는다","같은 사이트라는 사실만으로 모든 변경 요청이 정당해지지 않는다."],["상태 변경 경로의 토큰·출처 검증과 쿠키 동작을 확인한다","SameSite를 보조 방어로 두고 실제 요청 경로와 적용 조건을 함께 확인한다."],["쿠키 속성을 켜면 상태 변경 GET도 아무 검토 없이 유지한다","메소드 의미와 상태 변경 경로 설계도 별도로 점검해야 한다."]],'쿠키 속성은 요청 특성과 업무 흐름을 검토하는 설계의 일부다.');

const components = objective(w11,'components-api','외부 구성요소와 API도 같은 경계 안에 있다',[12,21,22],
  '사용자가 보지 않는 API나 외부 라이브러리는 보안 검토에서 빠지기 쉽지만 응용의 권한으로 자료를 다룰 수 있다.',
  ['라이브러리·프레임워크 등 구성요소는 응용과 같은 실행 문맥의 권한을 사용할 수 있으므로 알려진 결함이 전체 서비스의 피해로 이어질 수 있다. 다만 모든 구성요소가 항상 관리자 권한이라는 교안 표현은 과도하다. 실제 실행 계정·기능 도달성·구성·취약 버전을 확인하고 의존성 목록과 갱신·호환성 검증을 유지한다. 패치 이름만 확인하지 말고 배포된 버전과 영향 기능을 확인한다.',
   'API는 모바일·브라우저·서버가 호출하는 기능 경계이며 SOAP/XML·REST/JSON·RPC 같은 표현·상호작용 방식이 보안을 자동 보증하지 않는다. 앱 코드를 알게 되는 것 자체와 인증 우회는 다르므로 서버가 클라이언트를 믿지 않고 인증·객체/기능 인가·입력 검증·비용 제한·기록을 수행한다. 공개되지 않은 경로도 비밀 인증 수단이 아니다. 교안의 취약 API 항목은 역사적 분류로 보존하고 모든 API가 취약하다는 식으로 채점하지 않는다.'],
  '구성요소는 실제 권한·버전으로, API는 요청별 검증·인가로 평가한다.',
  [['의존성 관리','사용 구성요소와 버전·영향 추적','배포 버전과 보안 공지 대조'],['API 인증','요청 주체 확인','유효한 자격증명 검증'],['API 인가','주체가 이 대상과 작업을 쓸 수 있는지','자기 자료만 수정 허용']],
  '가상 모바일 앱의 API 주소가 알려졌지만 서버는 각 요청에서 사용자와 자료 권한을 확인한다.',
  ['API 주소나 앱 구조가 알려진 사실을 즉시 침해 성공으로 취급하지 않는다.','서버의 인증·객체 인가·검증·실행 권한과 실제 노출 결과를 점검한다.'],
  '클라이언트 은닉 대신 서버 경계가 보호의 중심이어야 한다.',
  '모바일 앱 안의 주소를 숨기면 서버 검증을 생략해도 된다는 생각은 클라이언트 분석 가능성을 무시한다.',
  '취약 라이브러리가 있는지 볼 때 이름만으로 충분하지 않은 이유는?', '버전·설정·노출 기능·실행 권한·배포 상태에 따라 악용 가능성과 영향이 달라지기 때문이다.', ['component-privileges','api-generalization']);
q(w11,components,'component-execution-rights','concept',[21],'취약 구성요소의 피해 범위를 판단하는 정확한 기준은?',2,[["구성요소가 하나 취약하면 서버 전체 관리자 권한 획득으로 확정한다","취약점 존재와 실제 권한·영향은 별도 조건이다."],["이름에 라이브러리라고 되어 있으면 보안 영향이 없다고 본다","구성요소의 명칭이 취약 기능의 도달성과 권한을 대신하지 않는다."],["실제 실행 계정·권한·도달 기능과 취약 버전을 확인한다","구성요소의 권한과 노출 조건에 따라 실제 영향 범위가 달라진다."],["개발 환경의 버전만 보고 운영 피해 범위를 결정한다","실제 배포된 버전과 설정을 확인해야 한다."]],'라이브러리 취약성의 심각함을 인정하되 무조건 관리자라는 과장은 피한다.');
q(w11,components,'dependency-deployed-version','application',[21],'가상 팀이 개발 PC의 패키지만 갱신하고 운영 배포 버전은 확인하지 않았다. 남은 확인은?',0,[["실제 배포 구성요소의 버전·설정·동작 검증","개발 PC의 갱신이 운영 산출물 교체를 입증하지 않는다."],["잠금 파일 이름이 그대로인지 확인하면 운영 버전도 증명된다","파일 이름만으로 배포된 구성요소의 실제 버전을 알 수 없다."],["개발 PC에서 설치 명령이 성공했으므로 운영 검증을 생략한다","개발 환경 결과와 운영 배포 상태를 구분해야 한다."],["운영이 정상 응답하면 취약 버전이 없다고 확정한다","정상 응답은 구성요소 버전과 취약성의 부재를 보증하지 않는다."]],'의존성 관리의 완료는 설치 의도뿐 아니라 배포된 결과를 확인해야 한다.');
q(w11,components,'api-address-not-auth','application',[22],'가상 모바일 앱의 API 주소가 외부에 알려졌다. 이 사실만으로 확정할 수 없는 것은?',3,[["API의 호출 위치가 외부에 알려졌다","상황이 직접 제시하는 제한된 사실이다."],["주소 비공개만을 유일한 보호로 삼으면 안 된다","API 주소의 발견 가능성과 인증·인가 설계를 구분해야 한다."],["실제 응답을 처리하는 서버의 권한 검사를 확인해야 한다","우회 여부와 영향 판단을 위해 필요한 조사다."],["사용자 인증과 객체 인가가 이미 우회되었다","API 주소 발견은 접근 경계 우회 성공의 증거가 아니다."]],'공개 가능한 경로 정보와 비밀 자격증명·인가 실패를 구분한다.');
q(w11,components,'json-not-security','contrast',[22],'API가 JSON을 사용하므로 인증·인가를 생략해도 된다는 주장에 대한 평가는?',1,[["옳다, JSON 문법이 맞으면 요청 주체도 자동 인증된다","표현 문법은 사용자 신원을 증명하지 않는다."],["틀리다, 표현 형식과 요청 주체·객체 권한 검증은 별개다","JSON도 외부 요청의 데이터이며 신원·권한 검증을 대신하지 않는다."],["옳다, 객체 ID가 JSON 안에 있으면 해당 객체의 소유자다","입력 위치는 객체 권한을 증명하지 않는다."],["틀리다, JSON을 XML로 바꾸는 것만으로 인증·인가가 완성된다","표현 형식 교체만으로 접근 통제가 구현되지 않는다."]],'API의 보호는 형식 이름이 아니라 실제 서버 통제와 데이터 흐름에 달렸다.');

// The 2013 topics remain taught even where the handout discusses their merger/removal.
w11.objectives.find(o => o.id === owasp).explanation.push('교안의 2013 비교에서 직접 객체 참조와 기능 수준 접근통제는 접근 제어의 두 관점으로 이해한다. 검증되지 않은 리다이렉트·포워드는 외부 입력이 이동 목적지를 결정할 때 사용자를 의도 밖 위치로 보내거나 서버 내부 경계를 우회할 수 있는 문제다. 허용 목적지·상대 경로·권한을 검증해야 하며, 이후 목록에서 독립 이름이 빠졌다는 이유로 이 검사를 제거하지 않는다. 최종 2017판의 XXE는 XML 외부 자원 해석, 안전하지 않은 역직렬화는 외부 직렬 자료의 위험한 객체 복원, 로깅 부족은 발견·대응 연결의 실패라는 별도 원리로만 보충한다.');
w11.objectives.find(o => o.id === components).explanation.push('교안의 구성요소 사례는 HTTP 헤더처럼 평범해 보이는 입력도 취약한 프레임워크에서 강력한 표현식으로 평가되면 서버 권한의 동작으로 이어질 수 있음을 보여 준다. 헤더라는 위치나 JSON·XML이라는 형식만으로 신뢰하지 말고, 실제 파서와 평가 기능 및 사용하는 구성요소의 수정 여부를 확인한다. 실습에서는 표현식·주입 문자열을 제공하지 않고 입력 경로와 실행 권한의 연결만 분석한다.');
q(w11,owasp,'redirect-validation','application',[9,10],'가상 서비스가 사용자 지정 이동 주소를 검사 없이 사용한다. 해당 항목이 특정 Top 10에서 빠졌다는 이유로 검사를 생략해도 되는가?',2,[["된다. Top 10에 없으면 사용자 지정 목적지는 항상 신뢰한다","위험 목록이 서비스별 입력 검증을 대신하지 않는다."],["안 된다. 목적지를 URL 인코딩하기만 하면 모든 신뢰 검증이 끝난다","표현 변경은 목적지의 신뢰성을 검증하지 않는다."],["안 된다. 허용 목적지와 권한 경계를 검증해야 한다","목록 등재 여부와 무검증 이동 값의 위험은 별개다."],["된다. 로그인한 사용자가 보낸 이동 값은 외부 주소도 자동 승인한다","로그인 여부만으로 모든 목적지를 허용하는 것은 적절하지 않다."]],'최종 목록의 독립 항목 유무와 무관하게 외부 이동 목적지의 검증은 필요하다.');

correction(w11,'post-security',[2,3,22], 'POST는 길이 제한이 없고 헤더에 포함되어 데이터가 노출되지 않으며 GET보다 안전하다고 표현한다.', 'POST 데이터는 일반적으로 본문에 놓이며 본문 자체가 암호화되지는 않는다. 서버·중계기는 크기 제한을 적용할 수 있다. GET·POST 모두 HTTPS·입력 검증·인가·민감정보 및 로그 최소화가 필요하다.', 'GET/POST의 의미는 배우되 POST 자동 기밀성·무제한 용량·CSRF 자동 방어는 오답으로 처리한다.', 'verified', [R.http,R.csrf]);
correction(w11,'http-version',[1], 'HTTP를 주소창·HTML로 한정하고 TCP/UDP·기본 포트·1.1 현재 대부분이라는 표현을 세대 구분 없이 제시한다.', 'HTTP는 여러 클라이언트와 다양한 표현을 다루는 응용 프로토콜이다. HTTP/1.1의 TCP 지속 연결 기본과 HTTP/3의 QUIC을 구분한다. 교안의 1.0/1.1 비교는 역사적 기본 동작이며 현재 보급률은 이번 확인에서 측정하지 않았다.', '모든 HTTP가 동일 연결 모델이라는 주장과 현재 보급률 문제는 제외한다. HTTP/3는 현대 보충으로 표시한다.', 'contextualized', [R.http,R.http3]);
correction(w11,'http-status',[4], '201을 PUT 요청 성공으로만 정의하고 500을 SQL 인젝션 취약점 확인과 연결한다.', '201은 새 자원 생성 의미로 POST 등에서도 사용된다. 401은 유효한 인증 정보 부족과 인증 요구, 500은 일반 서버 오류다. 500만으로 특정 주입 결함·성공을 확인할 수 없다.', '메소드 전용 201이나 오류 하나의 침해 확정을 정답으로 쓰지 않는다.', 'verified', [R.http]);
correction(w11,'url-context',[5], '플러스는 공백, 골뱅이는 mailto, 물결표는 홈 경로라는 설명을 URL 전체의 보편 규칙처럼 제시한다.', '플러스 공백 해석은 폼 인코딩 문맥이다. URI 일반 문법과 스킴별 해석을 구분한다. 퍼센트 인코딩은 암호화가 아니고 조각 식별자는 일반 HTTP 요청 대상에 포함되지 않는다. 물결표 홈 연결도 서버별 관례다.', '문맥을 명시한 구성요소 역할을 묻고 인코딩을 비밀 보호로 채점하지 않는다.', 'verified', [R.uri,R.http]);
correction(w11,'client-validation',[8], '사용자 입력 검증을 서버에서 처리하지 않고 클라이언트 JavaScript로 구현한다고 설명한다.', '클라이언트 검증은 사용성 보조이며 서버에서 타입·범위·업무 규칙·인가를 강제해야 한다. JavaScript라는 언어도 클라이언트 전용으로 한정하지 않는다.', '클라이언트 값의 출처만으로 신뢰하지 않으며 서버 검증 생략은 오답으로 한다.', 'verified', [R.validation]);
correction(w11,'html-history',[7,8], 'ENQUIRE와 HTML의 기원, HTML 4 계열 ISO 표준과 HTML5·플러그인 변화를 한 흐름으로 단정한다.', 'CERN의 ENQUIRE는 웹 이전의 역사적 맥락이며 오늘날 HTML의 정의·기능과 혼동하지 않는다. 현재 HTML은 WHATWG Living Standard에서 발전한다. 과거 표준화 연도를 모든 HTML 버전의 동일성으로 읽지 않는다.', '역사 배경은 유지하되 연도·최초 명명 세부를 채점하지 않는다. 플러그인 없이 기능을 제공해도 입력 신뢰가 자동 생기지 않음을 학습한다.', 'contextualized', [R.cern,R.html]);
correction(w11,'owasp-version',[9,10,11,12,19,20,22], '2017 열이 XSS A3·공격 방어 A7·CSRF A8·취약 API A10으로 공식 최종판과 다르다.', '공식 2017 최종판은 A1 인젝션, A2 취약 인증, A3 민감 자료 노출, A4 XXE, A5 취약 접근제어, A6 설정 오류, A7 XSS, A8 안전하지 않은 역직렬화, A9 취약 구성요소, A10 불충분한 로깅·모니터링이다. 교안은 후보안 계열과 일치하는 것으로 추정되나 원전 후보판 자체는 미확인이다.', '최종판 불일치는 확인 사실, 정확한 후보판 귀속은 추정으로 분리한다. 잘못된 2017 순위 암기 문제를 만들지 않으며 교안의 CSRF·API·공격 방어 개념은 보존한다.', 'contextualized', [R.top]);
correction(w11,'attack-protection',[10,12,19], '대부분의 앱·API는 방어 기능이 없고 패치하면 보호된다는 식으로 포괄적으로 표현한다.', '서비스별 실제 통제를 확인해야 한다. 입력 검증·탐지·로깅·경보·대응과 신속한 패치는 다른 역할이다. 목록 번호가 달라져도 탐지·대응 필요성은 남는다.', '모든 앱의 방어 부재를 정답으로 쓰지 않고 가상 기록에서 남은 통제 공백을 묻는다.', 'contextualized', [R.top,R.validation]);
correction(w11,'xxe-context',[13], 'XXE를 SQL·OS·LDAP 인젝션과 같은 예로 나열한다.', '신뢰 경계 실패라는 공통점은 있지만 XXE는 XML 파서의 외부 엔티티 처리 문제이고 공식 2017 최종판은 별도 항목으로 다룬다. SQL 매개변수화 하나로 XML 파서 설정까지 보호되지 않는다.', '분류 이름보다 해석기의 원인과 적절한 통제를 구분한다. 작동하는 페이로드는 제외한다.', 'contextualized', [R.top,R.injection]);
correction(w11,'xss-controls',[15], '교안의 실행 가능한 스크립트와 쿠키 전송 예를 그대로 따라 할 수 있는 형태로 제시한다.', '학습 앱은 실행 문자열을 보존하지 않고 브라우저 코드 해석 경계·텍스트 출력·문맥별 인코딩·필요한 정화를 원인과 방어로 설명한다. HttpOnly·CSP는 보충이며 원인 수정의 대체가 아니다.', '실제 공격 코드와 대상은 제공·실행하지 않는다. 관찰·방어 선택의 가상 사례만 채점한다.', 'contextualized', [R.xss,R.session]);
correction(w11,'storage-encryption',[18], '저장 자료를 주입으로 조회할 때 자동 복호화 가능성을 간략히 언급한다.', '저장 암호화는 매체 보호이며 응용이 정당하게 복호화할 수 있는 경로의 인가·질의 결함까지 막지 못한다. 자료 최소화·키 관리·전송 보호·응용 권한이 함께 필요하다.', '암호화가 인젝션·인가 결함을 자동 해결한다는 선택지는 오답으로 한다.', 'verified', [R.storage,R.injection]);
correction(w11,'component-privileges',[21], '구성요소가 대부분 응용 관리자 권한으로 실행된다고 일반화한다.', '라이브러리는 응용의 실행 문맥과 권한을 이용할 수 있으나 모든 경우 OS 관리자라는 뜻은 아니다. 실제 계정·기능·버전·구성으로 악용 가능성과 영향을 판단한다.', '실제 권한·배포 버전을 확인하도록 묻고 무조건 관리자 권한 획득은 채점하지 않는다.', 'verified', [R.top]);
correction(w11,'api-generalization',[12,22], 'API 대부분이 취약하며 앱 분석으로 인증 정보를 활용하면 공격이 되는 식으로 단정한다.', 'API 형식이나 클라이언트 분석 사실만으로 인증·인가 우회를 확정할 수 없다. 서버의 자격증명 검증·객체 및 기능 인가·입력 검증·기록을 확인해야 한다.', 'API 주소 인지와 실제 침해 성공을 구별하고 정당한 서버 통제를 평가한다.', 'contextualized', [R.authorization,R.validation,R.top]);
