coverage(w11,[2,3], 'OPTIONS·HEAD·PUT·TRACE·DELETE·GET/POST 의미와 보안', [methods]);
coverage(w11,[4,5], '요청·응답·상태 코드·URL 구성·인코딩', [urls]);
coverage(w11,[6], '위협 흐름·정보 수집·약점 확인을 방어 관점으로 분석', [webarch], 'covered', '대상 선정·실행·백도어·흔적 제거는 실제 활동으로 제공하지 않음.');
coverage(w11,[7,8], '정적/동적 웹·서버/DB/HTML/JavaScript·검증 책임', [webarch], 'covered', '역사 연도 세부는 정정 근거와 함께 비채점 맥락으로 표시.');
