coverage(w11,[11,12], '교안의 열 가지 위험 개요와 업무 영향', [owasp,injection,session,xss,access,config,csrf,components], 'historical', '교안의 잘못된 최종 순위는 채점 제외하되 모든 위험 개념 유지.');
