coverage(w11,[23], '내용 없는 마지막 서식 페이지', [], 'blank', '텍스트 추출은 쪽번호뿐이며 원본 렌더에서도 빈 서식만 확인.');

// Tighten page provenance for objectives that span summary and comparison pages.
w9.objectives.find(o => o.id === dos).explanation.push('LAND의 역사적 사례는 출발지와 목적지 주소·포트를 자기 자신으로 보이게 하여 취약한 TCP 구현의 처리를 교란하는 구조다. Ping of Death는 단순히 큰 정상 ping이 아니라 허용 길이를 벗어나도록 만들어지는 재조립 결과를 안전하게 처리하지 못한 과거 구현의 문제다. Smurf도 브로드캐스트 전달과 다수 응답이 가능한 환경이라는 조건이 필요하다. 이름을 현재 위험 순위나 모든 장비의 동일 반응으로 일반화하지 않는다.');
w9.objectives.find(o => o.id === ddos).explanation.push('첫 SYN을 버리고 재시도를 보는 방식은 정상 클라이언트의 재전송 특성을 이용하려는 완화다. 재전송 여부는 사용자 신원 인증이 아니며 지연·손실·구현 차이의 영향을 받는다. 정상적인 TCP 연결을 성립시킨 출발 주소도 프록시·공유 NAT·감염 단말일 수 있어 실제 행위자의 신원과 일치한다고 단정하지 않는다. 상위 완화, 연결 자원 관리, 응용별 비용 제한과 정상 이용자 영향의 관찰을 함께 고려한다.');
w9.objectives.find(o => o.id === accounts).explanation.push('역할의 취지를 비교하면 Administrators는 폭넓은 관리, Users는 일반 작업, Guests는 제한된 임시 이용 맥락으로 읽는다. Backup Operators는 백업·복구, Account Operators는 서버 역할에 따른 계정·그룹 관리, Server Operators는 서버 운영과 서비스 관련 작업을 맡는 분류다. Power Users는 과거 응용 호환성과 권한 모델의 역사와 연결되므로 현대의 작은 관리자라고 단정하지 않는다. 역할 명칭의 취지와 실제 정책에서 부여된 구체 권한을 나누어 확인한다.');
w10.objectives.find(o => o.id === wep).explanation.push('WEP 송신 흐름은 데이터의 CRC-32 계산, IV와 비밀키에 기반한 키스트림 생성, 데이터·ICV와 키스트림의 XOR, 공개 IV·KeyID를 붙이는 순서로 이해한다. 수신자는 같은 키스트림으로 데이터를 복원하고 CRC를 다시 계산해 비교한다. ICV가 맞지 않으면 무결성 확인에 실패한 프레임이며 교안처럼 별도 재전송 요청 메시지가 반드시 생긴다고 외우지 않는다. 캡처·재전송·연결 방해·키 분석 도구의 역할은 서로 다르고 일부는 능동 개입이므로 모두 수동 관찰이라 부르지 않는다.');
w10.objectives.find(o => o.id === mac).pages = [19,20,25,26];
w10.objectives.find(o => o.id === risks).pages = [4,5,6,7,8,9,21];
w11.objectives.find(o => o.id === session).pages = [11,14,19];
w11.objectives.find(o => o.id === xss).pages = [11,14,15];
w11.objectives.find(o => o.id === csrf).pages = [12,15,20];

const { validateWeek } = await import('../../dist/src/domain/content.js');
const seen = new Set();
for (const w of weeks) {
  applyQuestionRevisions(w);
  validateWeek(w);
  const pageSet = new Set(w.coverage.flatMap(e => e.pages));
  if (pageSet.size !== w.source.pages) throw new Error(`Missing pages: ${w.id}`);
  for (const o of w.objectives) {
    const assigned = w.questions.filter(q => q.objectiveId === o.id);
    if (assigned.length < 3) throw new Error(`Insufficient genuine questions: ${o.id}`);
    for (const item of assigned) if (!item.sourcePages.every(p => o.pages.includes(p))) throw new Error(`Objective provenance: ${item.id}`);
  }
  for (const item of w.questions) {
    if (seen.has(item.id) || seen.has(item.prompt)) throw new Error(`Duplicate question: ${item.id}`);
    seen.add(item.id); seen.add(item.prompt);
  }
  const filename = path.join(root, 'dist', 'content', `week-${String(w.number).padStart(2,'0')}.json`);
  applyCorrectionComparisons(w);
  mkdirSync(path.dirname(filename), { recursive: true });
  writeFileSync(filename, JSON.stringify(w, null, 2).replace(/\n/g, '\r\n') + '\r\n', 'utf8');
  const raw = readFileSync(filename);
  if (raw[0] === 239 && raw[1] === 187 && raw[2] === 191) throw new Error('BOM');
  validateWeek(JSON.parse(raw.toString('utf8')));
  console.log(JSON.stringify({week:w.number,objectives:w.objectives.length,questions:w.questions.length,corrections:w.corrections.length,pages:pageSet.size,families:new Set(w.questions.map(q=>q.family)).size}));
}
